"use client";

import type { ChartRoot } from "./chart-utils";
import { useMergedRef } from "../lib/form";
import { useEffect, useMemo, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { cn } from "../lib/cn";
import { useSyncRef } from "../hooks/use-latest";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { ChartAnnouncer, ChartEmpty } from "./chart-parts";
import { dockSpace, useDockedReadout } from "./chart-fit";
import { chartFocusClass, clamp, useElementWidth, resolveInstructions, itemAt } from "./chart-utils";
import { ChartDockHint, defaultCompact, useEntrance, type ChartTipAnchor } from "./heatmap";
import { useCoarsePointer } from "../hooks/use-media-query";
import { FlowTip, haloTextClass, useFontsLoaded, useFrameStore } from "./flow-utils";
import { ChartFigure } from "./chart-figure";
import { batchMarks, buildGraph, entranceOrder } from "./network-graph/model";
import { defaultNetworkGraphLabels, type NetworkGraphProps } from "./network-graph/types";
import { NO_ANCHOR, nameAnchor, nodeReadout } from "./network-graph/layout";
import { useGraphRefs } from "./network-graph/refs";
import { usePainter } from "./network-graph/use-painter";
import { useSimulationLayout } from "./network-graph/use-simulation";
import { useGraphView } from "./network-graph/use-view";
import { useGraphEntrance } from "./network-graph/use-entrance";
import { useGraphGestures } from "./network-graph/use-gestures";
import { graphKeyDown } from "./network-graph/keyboard";
import { useGraphNames } from "./network-graph/use-names";
import { GraphMarks, LitLayers, ZoomToolbar } from "./network-graph/layers";

export { type ForceSimulationOptions, type ForceSimulation, createForceSimulation } from "./network-graph/simulation";
export { type NetworkNode, type NetworkLink, type NetworkGroup } from "./network-graph/model";
export {
  type NetworkGraphLabels,
  defaultNetworkGraphLabels,
  type NetworkGraphProps,
  networkLegend,
} from "./network-graph/types";
export { type NetworkTableProps, NetworkTable } from "./network-graph/table";

/**
 * Who is connected to whom: services and their dependencies, people who work together, linked
 * pages. Laid out by a force simulation written here (link springs, charge, gravity, collision),
 * deterministic for the same data; graphs over 100 nodes use Barnes–Hut charge and grid collision.
 *
 * - The layout is computed in small chunks between frames, then nodes ripple out from the centre
 *   (the most connected first) and the links draw in. Data changes glide nodes to their new places.
 * - Hover or tap a node to light up its connections; drag it to pull the network along (it
 *   settles back with the simulation). Ctrl/⌘ + scroll, a pinch or the buttons zoom; drag the
 *   background to pan. Names are printed where they fit, more as you zoom in.
 * - Every moving frame (layout, ripple, glide, drag, pan, zoom) is written straight to the SVG:
 *   pan and zoom are one transform on the graph's layer, every dot of a colour is one path and
 *   every line of a width another (a frame rewrites a dozen paths, whatever the size of the
 *   graph), and React renders only when what is shown changes (a reading, a settled view).
 * - A reading dims each layer as a whole and draws the active node's ties and neighbours again
 *   on top, so a hover costs the same on 20 nodes or 500.
 * - Keyboard: arrows move to the nearest node in that direction, Page Up / Page Down step through
 *   every node in order, + / − zoom and 0 fits. The table view (NetworkTable) lists every node's
 *   connections.
 * - Reduced motion: the precomputed layout appears in place; dragging moves only that node.
 *
 * The pieces live in `network-graph/`: the data model and mark batches (`model.ts`), the force simulation
 * (`simulation.ts`), the refs that hold what is on screen (`refs.ts`), the painter (`use-painter.ts`), the chunked
 * layout (`use-simulation.ts`), the view (`use-view.ts`), the entrance (`use-entrance.ts`), pointer gestures
 * (`use-gestures.ts`), the keyboard model (`keyboard.ts`), name placement (`use-names.ts`) and the SVG layers
 * (`layers.tsx`).
 *
 * Keyboard: Tab focuses the graph; the arrow keys move to the nearest node in that direction, Page Up and Page Down step through every node in order, + and - zoom, 0 fits the view, Escape clears. With `onNodeClick`, Enter activates the node being read. The zoom buttons form a toolbar and are also tab stops.
 * Accessibility: `role="figure"` named by the chart title, with the keyboard hint as its description (`aria-describedby`, and `aria-details` to the `ChartCard` table view); focusable only when interactive; keyboard moves announce the node with its group and connections. `NetworkTable` lists every node and its links as the table view.
 * Glass and motion: the plot has no backdrop blur. Reduced motion lays the graph out and moves it instantly.
 *
 * @example
 * ```tsx
 * import { NetworkGraph } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <NetworkGraph
 *       nodes={[{ id: "api" }, { id: "db" }, { id: "cache" }, { id: "web" }]}
 *       links={[
 *         { source: "web", target: "api" },
 *         { source: "api", target: "db" },
 *         { source: "api", target: "cache" },
 *       ]}
 *       aria-label="Service dependencies"
 *     />
 *   );
 * }
 * ```
 *
 * @see /charts/network-graph
 */
export function NetworkGraph({
  nodes,
  links,
  groups,
  height = 420,
  showLabels = "auto",
  forces,
  format: formatProp,
  locale,
  onNodeClick,
  emptyState,
  labels: labelOverrides,
  "aria-label": ariaLabel,
  className,
  ref: outerRef,
  ...rest
}: ChartRoot<NetworkGraphProps>) {
  const labels = useMemo(() => ({ ...defaultNetworkGraphLabels, ...labelOverrides }), [labelOverrides]);
  const format = formatProp ?? defaultCompact(locale);
  const reduced = useSheenReducedMotion();
  const coarse = useCoarsePointer();
  const rootRef = useRef<HTMLDivElement>(null);
  const rootMerged = useMergedRef(rootRef, outerRef);
  const [measureRef, width] = useElementWidth<HTMLDivElement>();
  const play = useEntrance(rootRef, reduced);
  const fonts = useFontsLoaded(); // names are placed with measureText: place them again once the font arrives
  const tip = useFrameStore<ChartTipAnchor>();

  const graph = useMemo(() => buildGraph(nodes, links, groups), [nodes, links, groups]);
  const n = graph.nodes.length;
  const ids = useMemo(() => graph.nodes.map((g) => g.id), [graph]);
  const forcesKey = JSON.stringify(forces ?? {});
  // The layout follows the box's shape (in coarse steps, so a resize doesn't re-run it every pixel).
  const aspect = width > 0 ? clamp(Math.round(((width - 60) / Math.max(1, height)) * 4) / 4, 0.5, 3) : 0;
  const docked = useDockedReadout(width);

  /* ---------- What is on screen, kept outside React (see network-graph/refs.ts) ---------- */

  const R = useGraphRefs(reduced);
  const { reducedRef, dockRef, settleTimerRef, gestureRef, posRef, svgRef, viewLayerRef, nameLayerRef, ringRef } = R;
  const { linkFadeRef, linkLayerRef, nodeLayerRef, litLinkLayerRef, litNodeLayerRef } = R;
  useSyncRef(reducedRef, reduced);

  // A moving frame rewrites a dozen paths, not one element per dot and per line: the browser
  // restyles and re-lays-out a handful of elements whatever the size of the graph.
  const batches = useMemo(() => batchMarks(graph), [graph]);

  const [layoutVersion, setLayoutVersion] = useState(0);
  const [introPlayed, setIntroDone] = useState(false);
  const introDone = introPlayed || reduced;
  // Bumped once motion stops (a drag, pan, zoom or glide settled): the names are placed again.
  const [settled, setSettled] = useState(0);
  const settle = () => {
    window.clearTimeout(settleTimerRef.current);
    settleTimerRef.current = window.setTimeout(() => setSettled((v) => v + 1), 90);
  };
  useEffect(() => () => window.clearTimeout(settleTimerRef.current), [settleTimerRef]);

  /* ---------- Entrance order: breadth first from the most connected node ---------- */

  const rank = useMemo(() => entranceOrder(graph), [graph]);

  /* ---------- Interaction state (React renders on these, not per frame) ---------- */

  const [active, setActive] = useState<number | null>(null);
  const [source, setSource] = useState<"keyboard" | "pointer">("pointer");
  const [dragging, setDragging] = useState<number | null>(null);
  const [panning, setPanning] = useState(false);
  const act = active !== null && active < n ? active : null;

  /* ---------- Painting, layout, view, entrance, gestures, keyboard (see network-graph/) ---------- */

  const { anchorOf } = usePainter({ R, graph, batches, rank, n, ids, tip, act, dragging });
  const { startLive } = useSimulationLayout({ R, graph, n, aspect, forcesKey, settle, setLayoutVersion });
  const { setView, zoomBy, fit, screenOf, toSim } = useGraphView({
    R,
    graph,
    n,
    width,
    height,
    layoutVersion,
    act,
    source,
    settle,
  });
  const hasLayout = layoutVersion > 0;
  useGraphEntrance({ R, play, hasLayout, introDone, reduced, setIntroDone });
  const gestures = useGraphGestures({
    R,
    graph,
    n,
    act,
    source,
    hasWidth: width > 0,
    onNodeClick,
    setActive,
    setSource,
    setDragging,
    setPanning,
    settle,
    startLive,
    setView,
    zoomBy,
    screenOf,
    toSim,
  });
  const onKeyDown = (event: KeyboardEvent) =>
    graphKeyDown(event, { graph, n, act, rank, pos: posRef.current, onNodeClick, zoomBy, fit, move: gestures.move });

  /* ---------- Readouts ---------- */

  const connectionsLabel = labels.connections;
  const valueLabel = labels.value;
  const readoutOf = (i: number) => nodeReadout(itemAt(graph.nodes, i), connectionsLabel, valueLabel, format);
  const dock = useMemo(
    () =>
      docked
        ? dockSpace(
            width,
            graph.nodes.map((node) => nodeReadout(node, connectionsLabel, valueLabel, format)),
          )
        : 0,
    [docked, width, graph, connectionsLabel, valueLabel, format],
  );
  useSyncRef(dockRef, dock);

  const lit = useMemo(() => {
    const set = new Set<number>();
    if (act !== null) {
      set.add(act);
      for (const j of itemAt(graph.nodes, act).neighbours) set.add(j);
    }
    return set;
  }, [act, graph]);
  const any = act !== null;

  /* ---------- Names: placed when the view settles (see network-graph/use-names.ts) ---------- */

  const names = useGraphNames({
    R,
    graph,
    act,
    lit,
    dragging,
    introDone,
    showLabels,
    width,
    height,
    dock,
    coarse,
    settled,
    layoutVersion,
    fonts,
    tip,
    screenOf,
    anchorOf,
  });

  // The reading's copies: the active node's ties in its colour, its neighbours and itself at full strength.
  const litNode = act !== null ? itemAt(graph.nodes, act) : null;

  if (n === 0) {
    return (
      <ChartEmpty height={height} aria-label={ariaLabel} className={className}>
        {emptyState}
      </ChartEmpty>
    );
  }

  let tooltip: ReactNode = null;
  let announcement = "";
  if (act !== null) {
    const r = readoutOf(act);
    if (dragging === null) {
      tooltip = (
        <FlowTip
          title={r.title}
          rows={r.rows}
          anchor={NO_ANCHOR}
          bounds={{ w: width, h: height + dock }}
          docked={docked}
          store={tip}
        />
      );
    }
    const neighbourNames = itemAt(graph.nodes, act).neighbours.map((j) => itemAt(graph.nodes, j).label);
    // The value row reads label first ("value 14"); the others value first ("6 connections").
    announcement = `${r.title}: ${r.rows.map((row) => (row.label === labels.value ? `${row.label} ${row.value}` : `${row.value} ${row.label}`).trim()).join(", ")}. ${
      neighbourNames.length > 0
        ? labels.connectedTo(neighbourNames.slice(0, 8), Math.max(0, neighbourNames.length - 8))
        : ""
    }`;
  }

  return (
    <div {...rest} ref={rootMerged} className={cn("relative flex w-full min-w-0 flex-col", className)}>
      <div ref={measureRef} className="relative w-full" style={{ height: height + dock, paddingTop: dock }}>
        <ChartFigure
          as="div"
          roleDescription={labels.roleDescription}
          label={ariaLabel}
          description={resolveInstructions(labels.instructions)}
          tabIndex={0}
          onKeyDown={onKeyDown}
          onBlur={() => setActive(null)}
          className={cn("relative h-full w-full overflow-hidden rounded-sheen-sm", chartFocusClass)}
          style={{ height }}
        >
          {width > 0 && (
            <svg
              ref={svgRef}
              aria-hidden
              // Drawn left to right in every writing direction: text anchors stay physical under dir="rtl".
              direction="ltr"
              width={width}
              height={height}
              className={cn(
                "block overflow-visible select-none",
                panning || dragging !== null ? "cursor-grabbing" : act !== null ? "cursor-grab" : "cursor-default",
              )}
              style={{ touchAction: "pan-x pan-y" }}
              onPointerDown={gestures.onPointerDown}
              onPointerMove={gestures.onPointerMove}
              onPointerUp={gestures.onPointerUp}
              onPointerCancel={gestures.onPointerCancel}
              onPointerLeave={(e) => {
                if (e.pointerType === "mouse" && !gestureRef.current) setActive(null);
              }}
            >
              {/* The graph in simulation units: pan and zoom are this layer's one transform. */}
              {/* pointer-events none: the graph hit-tests in JS (nearest dot), so the browser never walks every shape on a mouse move. */}
              <g ref={viewLayerRef} data-dim={act !== null ? "" : undefined} className="group/net pointer-events-none">
                <GraphMarks
                  batches={batches}
                  linkFade={linkFadeRef}
                  linkLayer={linkLayerRef}
                  nodeLayer={nodeLayerRef}
                />
                {litNode && (
                  <LitLayers
                    graph={graph}
                    litNode={litNode}
                    litLinkLayer={litLinkLayerRef}
                    litNodeLayer={litNodeLayerRef}
                  />
                )}
                {/* The active node's ring (placed by the painter). */}
                <circle
                  ref={ringRef}
                  fill="none"
                  strokeWidth={1.5}
                  vectorEffect="non-scaling-stroke"
                  className="stroke-sheen-fg forced-colors:stroke-[Highlight]"
                  style={{ display: "none" }}
                />
              </g>

              {/* Names (screen px, moved with the pan; they fade in once the entrance is done). */}
              <g
                ref={nameLayerRef}
                className="pointer-events-none motion-ok:transition-opacity motion-ok:duration-(--sheen-duration-slow)"
                style={{ opacity: introDone ? 1 : 0 }}
              >
                {names.map((nm) => (
                  <text
                    key={nm.i}
                    data-id={nm.i}
                    dy="0.35em"
                    textAnchor={nameAnchor(nm.side)}
                    className={cn(
                      "text-2xs font-medium",
                      haloTextClass,
                      any && !lit.has(nm.i)
                        ? "fill-sheen-fg-subtle forced-colors:fill-[GrayText]"
                        : "fill-sheen-fg forced-colors:fill-[CanvasText]",
                      act === nm.i && "font-semibold",
                    )}
                  >
                    {nm.text}
                  </text>
                ))}
              </g>
            </svg>
          )}
        </ChartFigure>

        <ZoomToolbar labels={labels} top={dock + 8} zoomBy={zoomBy} fit={fit} />
        {tooltip ?? (docked && <ChartDockHint>{labels.hint}</ChartDockHint>)}
      </div>
      <ChartAnnouncer text={source === "keyboard" ? announcement : ""} />
    </div>
  );
}

import type { KeyboardEvent } from "react";
import { itemAt } from "../chart-utils";
import type { Graph } from "./model";
import type { NetworkGraphProps } from "./types";

/** What a key press needs to know: the graph, the active node, the entrance order, positions and the view's actions. */
export type KeyContext = {
  graph: Graph;
  n: number;
  act: number | null;
  /** Entrance order of each node; the one with rank 0 is where the arrows start from. */
  rank: number[];
  /** Node positions (simulation units), or null before the layout. */
  pos: number[] | null;
  onNodeClick: NetworkGraphProps["onNodeClick"];
  zoomBy: (factor: number) => void;
  fit: () => void;
  move: (i: number | null, from: "keyboard" | "pointer") => void;
};

/**
 * The keyboard model: arrows move to the nearest node in that direction, Page Up / Page Down step through every
 * node in order, Home / End jump to the first and last, + / − zoom, 0 fits, Enter activates (with `onNodeClick`)
 * and Escape clears the reading.
 */
export function graphKeyDown(
  event: KeyboardEvent,
  { graph, n, act, rank, pos, onNodeClick, zoomBy, fit, move }: KeyContext,
) {
  if (n === 0) return;
  let next: number | null | undefined;
  const key = event.key;
  if (key === "+" || key === "=") {
    zoomBy(1.4);
    event.preventDefault();
    return;
  }
  if (key === "-" || key === "_") {
    zoomBy(1 / 1.4);
    event.preventDefault();
    return;
  }
  if (key === "0") {
    fit();
    event.preventDefault();
    return;
  }
  const P = pos;
  const px = (i: number) => P?.[i * 2] ?? 0;
  const py = (i: number) => P?.[i * 2 + 1] ?? 0;
  const start = rank.indexOf(0);
  switch (key) {
    case "PageDown":
      next = act === null ? 0 : Math.min(n - 1, act + 1);
      break;
    case "PageUp":
      next = act === null ? 0 : Math.max(0, act - 1);
      break;
    case "Home":
      next = 0;
      break;
    case "End":
      next = n - 1;
      break;
    case "ArrowRight":
    case "ArrowLeft":
    case "ArrowUp":
    case "ArrowDown": {
      if (act === null) {
        next = start >= 0 ? start : 0;
        break;
      }
      const [dx, dy] =
        key === "ArrowRight" ? [1, 0] : key === "ArrowLeft" ? [-1, 0] : key === "ArrowUp" ? [0, -1] : [0, 1];
      let best: number | null = null;
      let bestScore = Infinity;
      let fallback: number | null = null;
      let fallbackScore = Infinity;
      for (let i = 0; i < n; i++) {
        if (i === act) continue;
        const vx = px(i) - px(act);
        const vy = py(i) - py(act);
        const along = vx * dx + vy * dy;
        if (along <= 0.5) continue;
        const across = Math.abs(vx * dy - vy * dx);
        const score = along + across * 2.5;
        if (across <= along * 1.2) {
          if (score < bestScore) {
            bestScore = score;
            best = i;
          }
        } else if (score < fallbackScore) {
          fallbackScore = score;
          fallback = i;
        }
      }
      next = best ?? fallback ?? act;
      break;
    }
    case "Enter":
    case " ": {
      if (act === null || !onNodeClick) return;
      const node = itemAt(graph.nodes, act);
      onNodeClick({
        id: node.id,
        label: node.label,
        group: node.group,
        connections: node.neighbours.map((j) => itemAt(graph.nodes, j).id),
      });
      event.preventDefault();
      return;
    }
    case "Escape":
      if (act === null) return;
      next = null;
      break;
    default:
      return;
  }
  event.preventDefault();
  move(next ?? null, "keyboard");
}

"use client";

import { memo, type RefObject } from "react";
import { cn } from "../../lib/cn";
import { itemAt } from "../chart-utils";
import { markGlow } from "../flow-utils";
import { ToolIcon } from "./layout";
import type { Batches, GNode, Graph } from "./model";
import type { NetworkGraphLabels } from "./types";

/**
 * Dots and lines: rendered once per data set and never restyled one by one. A reading dims each layer as a whole
 * (one opacity per layer) and draws its own copies of the active node's ties and neighbours on top (see
 * {@link LitLayers}), so a hover costs the same on a 20-node graph and a 500-node one. Memoised on the batches: the
 * painter positions the marks, React only creates them.
 */
export const GraphMarks = memo(function GraphMarks({
  batches,
  linkFade,
  linkLayer,
  nodeLayer,
}: {
  batches: Batches;
  linkFade: RefObject<SVGGElement | null>;
  linkLayer: RefObject<SVGGElement | null>;
  nodeLayer: RefObject<SVGGElement | null>;
}) {
  return (
    <>
      {/* Links: neutral hairlines (a constant screen width at any zoom). The outer group fades them in on first view. */}
      <g ref={linkFade}>
        <g
          ref={linkLayer}
          className="forced-color-adjust-none group-data-[dim]/net:opacity-20 motion-ok:transition-opacity motion-ok:duration-(--sheen-duration-fast)"
        >
          {batches.links.map((b) => (
            <path
              key={b.w}
              data-id={String(b.w)}
              fill="none"
              strokeLinecap="round"
              strokeOpacity={0.34}
              strokeWidth={b.w}
              vectorEffect="non-scaling-stroke"
              className="stroke-sheen-fg-subtle forced-colors:stroke-[CanvasText]"
            />
          ))}
        </g>
      </g>

      {/* Nodes: dots in their group's colour with a 2px surface ring, one path per colour, drawn by the painter.
          Hit testing is done in JS (the nearest dot within reach), so no invisible hit circles are drawn. */}
      <g
        ref={nodeLayer}
        className="forced-color-adjust-none group-data-[dim]/net:opacity-25 motion-ok:transition-opacity motion-ok:duration-(--sheen-duration-fast)"
      >
        {batches.nodes.map((b) => (
          <path
            key={b.color}
            data-id={b.color}
            fill={b.color}
            strokeWidth={2}
            vectorEffect="non-scaling-stroke"
            className="stroke-(--sheen-chart-surface) forced-colors:stroke-[CanvasText]"
          />
        ))}
      </g>
    </>
  );
});

/** The reading's copies: the active node's ties in its colour, its neighbours and itself at full strength. */
export function LitLayers({
  graph,
  litNode,
  litLinkLayer,
  litNodeLayer,
}: {
  graph: Graph;
  litNode: GNode;
  litLinkLayer: RefObject<SVGGElement | null>;
  litNodeLayer: RefObject<SVGGElement | null>;
}) {
  return (
    <g className="forced-color-adjust-none">
      <g ref={litLinkLayer}>
        {graph.links
          .filter((l) => l.s === litNode.index || l.t === litNode.index)
          .map((l) => (
            <line
              key={l.id}
              data-id={l.id}
              stroke={litNode.color}
              strokeOpacity={0.95}
              strokeWidth={l.width + 0.75}
              strokeLinecap="round"
              vectorEffect="non-scaling-stroke"
              className="forced-colors:stroke-[Highlight]"
            />
          ))}
      </g>
      <g ref={litNodeLayer}>
        {[...litNode.neighbours, litNode.index].map((i) => {
          const g = itemAt(graph.nodes, i);
          const on = i === litNode.index;
          return (
            <circle
              key={g.id}
              data-id={g.id}
              fill={g.color}
              strokeWidth={2}
              vectorEffect="non-scaling-stroke"
              className="stroke-(--sheen-chart-surface) forced-colors:stroke-[CanvasText]"
              style={on ? { filter: markGlow(g.color, 8) } : undefined}
            />
          );
        })}
      </g>
    </g>
  );
}

const toolButton = cn(
  "relative grid size-8 place-items-center rounded-sheen-sm text-sheen-fg-muted any-pointer-coarse:size-11",
  "hover:bg-sheen-hover hover:text-sheen-fg motion-ok:transition-colors motion-ok:duration-(--sheen-duration-fast)",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
);

/** Zoom controls: a small solid toolbar in the corner (no backdrop blur over a moving graph). */
export function ZoomToolbar({
  labels,
  top,
  zoomBy,
  fit,
}: {
  labels: Pick<NetworkGraphLabels, "zoomControls" | "zoomIn" | "zoomOut" | "fit">;
  /** Offset from the top of the plot box (below the docked readout). */
  top: number;
  zoomBy: (factor: number) => void;
  fit: () => void;
}) {
  return (
    <div
      role="toolbar"
      aria-label={labels.zoomControls}
      className="absolute right-2 z-1 flex flex-col gap-0.5 rounded-sheen-md border border-sheen-border bg-sheen-surface p-0.5 shadow-[0_1px_2px_var(--sheen-shadow-near),0_6px_16px_-8px_var(--sheen-shadow-far)]"
      style={{ top }}
    >
      <button
        type="button"
        className={toolButton}
        aria-label={labels.zoomIn}
        title={labels.zoomIn}
        onClick={() => zoomBy(1.4)}
      >
        <ToolIcon d="M8 3.5v9M3.5 8h9" />
      </button>
      <button
        type="button"
        className={toolButton}
        aria-label={labels.zoomOut}
        title={labels.zoomOut}
        onClick={() => zoomBy(1 / 1.4)}
      >
        <ToolIcon d="M3.5 8h9" />
      </button>
      <button type="button" className={toolButton} aria-label={labels.fit} title={labels.fit} onClick={fit}>
        <ToolIcon d="M3 6V3h3M10 3h3v3M13 10v3h-3M6 13H3v-3" />
      </button>
    </div>
  );
}

import { type Readout } from "../chart-fit";
import { clamp } from "../chart-utils";
import { type ChartTipAnchor } from "../heatmap";
import { r2 } from "../flow-utils";

/** The pan and zoom of the graph: scale `k` and the translation `tx`, `ty`. */
export type View = { k: number; tx: number; ty: number };
/** The smallest zoom scale. */
export const K_MIN = 0.25;
/** The largest zoom scale. */
export const K_MAX = 4;
/** Placeholder anchor for the tooltip: its real position is written to the tooltip store after each commit. */
export const NO_ANCHOR: ChartTipAnchor = { x: 0, y: 0, w: 0, h: 0 };
/** Dots (and their hit areas) grow a little as you zoom in and shrink a little as you zoom out. */
export const dotScale = (k: number) => clamp(Math.sqrt(k), 0.8, 1.35);
/** Entrance: nodes ripple out over the first part of it, by breadth-first rank; links fade in after. */
export const INTRO = 1.4;
/** How far the entrance ripple of the nodes spreads over the intro, as a fraction of it. */
export const SPREAD = 0.55;
/** ms of layout work per frame while the layout is computed: never a long task. */
export const BUDGET = 8;

/** The side of a node where its name is placed. */
export type Side = "right" | "left" | "below" | "above";
/** A placed name: which node, on which side of it, and its width. */
export type Name = { i: number; side: Side; text: string; w: number };

/** Offset of a name from its node's centre (screen px) for a dot of radius r. */
export function nameOffset(side: Side, r: number): [number, number] {
  return side === "right"
    ? [r + 4, 0]
    : side === "left"
      ? [-(r + 4), 0]
      : side === "below"
        ? [0, r + 9]
        : [0, -(r + 9)];
}
/** The SVG `text-anchor` of a name placed on the given side of its node. */
export const nameAnchor = (side: Side) => (side === "right" ? "start" : side === "left" ? "end" : "middle");

/** A circle as two arcs, so many dots of one colour can share one path. "" when it isn't drawn. */
export function circlePath(x: number, y: number, r: number) {
  if (!(r > 0.01) || !Number.isFinite(x + y)) return "";
  const R = r2(r);
  return `M${r2(x - r)},${r2(y)}a${R},${R} 0 1,0 ${r2(2 * r)},0a${R},${R} 0 1,0 ${r2(-2 * r)},0`;
}

/** The tooltip / docked readout of one node: its group, how many connections it has and its value. */
export function nodeReadout(
  g: { label: string; color: string; groupLabel?: string | null; neighbours: readonly number[]; value: number | null },
  connections: (n: number) => string,
  valueLabel: string,
  format: (n: number) => string,
): Readout {
  const rows: Readout["rows"] = [];
  if (g.groupLabel) rows.push({ label: "", value: g.groupLabel, color: g.color, kind: "rect" });
  rows.push({
    label: connections(g.neighbours.length),
    value: format(g.neighbours.length),
    color: g.groupLabel ? "transparent" : g.color,
    kind: "rect",
  });
  if (g.value !== null) rows.push({ label: valueLabel, value: format(g.value), color: "transparent", kind: "rect" });
  return { title: g.label, rows };
}

/** A 16px stroked icon for a toolbar button, drawn from one SVG path. */
export function ToolIcon({ d }: { d: string }) {
  return (
    <svg aria-hidden width={16} height={16} viewBox="0 0 16 16">
      <path d={d} fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

import { num, slotColor, type ChartColor, itemAt } from "../chart-utils";

/* ======================================================================
 * Data model
 * ====================================================================== */

/** A node of a NetworkGraph: an id, and optionally a label, a group and a size. */
export type NetworkNode = {
  id: string;
  /** Shown name. Default: the id. */
  label?: string;
  /** Id of the node's group (its colour). Nodes without a group share slot 1. */
  group?: string;
  /** Size of the node (its area). Optional. */
  value?: number;
};

/** A link of a NetworkGraph between two node ids, with an optional strength. */
export type NetworkLink = {
  source: string;
  target: string;
  /** Strength of the tie (the line's weight). Optional. */
  value?: number;
};

/**
 * A group of a NetworkGraph: an id, an optional label and an optional palette slot (the colour of its
 * nodes).
 */
export type NetworkGroup = {
  id: string;
  label?: string;
  /** Colour slot 1–8. Default: the group's position; past 8: neutral grey. */
  color?: ChartColor;
};

/** A laid-out node: its id, label, group, colour, value, radius and the indexes of its neighbours. */
export type GNode = {
  id: string;
  label: string;
  index: number;
  group: string | null;
  groupLabel: string | null;
  color: string;
  value: number | null;
  r: number;
  neighbours: number[];
};
/** A laid-out link between node indexes `s` and `t`, with its value and stroke width. */
export type GLink = { id: string; s: number; t: number; value: number; width: number };

/** Turns the nodes and links of the props into the node and link records of the layout (drops duplicate nodes, and links with an unknown end or to themselves). */
export function buildGraph(
  nodes: readonly NetworkNode[],
  links: readonly NetworkLink[],
  groups: readonly NetworkGroup[] | undefined,
) {
  const groupSlot = new Map<string, { slot: number; label: string }>();
  (groups ?? []).forEach((g, i) =>
    groupSlot.set(g.id, { slot: g.color ?? (i < 8 ? i + 1 : 0), label: g.label ?? g.id }),
  );
  const index = new Map<string, number>();
  const gnodes: GNode[] = [];
  const maxValue = Math.max(0, ...nodes.map((n) => Math.max(0, num(n.value))));
  for (const n of nodes) {
    if (index.has(n.id)) continue;
    if (n.group !== undefined && !groupSlot.has(n.group)) {
      const k = groupSlot.size;
      groupSlot.set(n.group, { slot: k < 8 ? k + 1 : 0, label: n.group });
    }
    const g = n.group !== undefined ? (groupSlot.get(n.group) ?? null) : null;
    const v = n.value === undefined ? null : Math.max(0, num(n.value));
    index.set(n.id, gnodes.length);
    gnodes.push({
      id: n.id,
      label: n.label ?? n.id,
      index: gnodes.length,
      group: n.group ?? null,
      groupLabel: g?.label ?? null,
      color: slotColor(g ? g.slot : 1),
      value: v,
      r: v !== null && maxValue > 0 ? 5 + Math.sqrt(v / maxValue) * 9 : 6,
      neighbours: [],
    });
  }
  const seen = new Map<string, GLink>();
  for (const l of links) {
    const s = index.get(l.source);
    const t = index.get(l.target);
    if (s === undefined || t === undefined || s === t) continue;
    const [a, b] = s < t ? [s, t] : [t, s];
    const id = `${a}-${b}`;
    const value = l.value === undefined ? 1 : Math.max(0, num(l.value));
    const prev = seen.get(id);
    if (prev) prev.value += value;
    else seen.set(id, { id, s: a, t: b, value, width: 1 });
  }
  const glinks = [...seen.values()];
  const maxLink = Math.max(0, ...glinks.map((l) => l.value));
  const weighted = links.some((l) => l.value !== undefined);
  for (const l of glinks) {
    l.width = weighted && maxLink > 0 ? 1 + 2.5 * Math.sqrt(l.value / maxLink) : 1.25;
    itemAt(gnodes, l.s).neighbours.push(l.t);
    itemAt(gnodes, l.t).neighbours.push(l.s);
  }
  return { nodes: gnodes, links: glinks, index, groups: groupSlot };
}

/** The graph as drawn: nodes and links by index, the id → index map and the groups' slots. */
export type Graph = ReturnType<typeof buildGraph>;

/**
 * The marks a frame rewrites: one path per colour holds every dot of that colour, one path per stroke width every
 * line of that width (a dozen paths whatever the size of the graph, so the browser restyles and re-lays-out a
 * handful of elements), plus the links by id for the reading's copies.
 */
export function batchMarks(graph: Graph) {
  const byColor = new Map<string, number[]>();
  for (const g of graph.nodes) {
    const list = byColor.get(g.color);
    if (list) list.push(g.index);
    else byColor.set(g.color, [g.index]);
  }
  const byWidth = new Map<number, GLink[]>();
  for (const l of graph.links) {
    const w = Math.round(l.width * 4) / 4;
    const list = byWidth.get(w);
    if (list) list.push(l);
    else byWidth.set(w, [l]);
  }
  return {
    nodes: [...byColor].map(([color, idx]) => ({ color, idx })),
    links: [...byWidth].map(([w, list]) => ({ w, list })),
    linkById: new Map(graph.links.map((l) => [l.id, l])),
  };
}
/** The drawing batches: nodes grouped by colour, links grouped by stroke width, and a lookup of links by id. */
export type Batches = ReturnType<typeof batchMarks>;

/** Entrance order: breadth first from the most connected node (then the next unvisited one), as a rank per node. */
export function entranceOrder(graph: Graph) {
  const n = graph.nodes.length;
  const order = new Array<number>(n).fill(-1);
  const byDegree = [...graph.nodes].sort((a, b) => b.neighbours.length - a.neighbours.length || a.index - b.index);
  let k = 0;
  for (const start of byDegree) {
    if (order[start.index] !== -1) continue;
    const queue = [start.index];
    order[start.index] = k++;
    while (queue.length > 0) {
      const i = queue.shift();
      if (i === undefined) break;
      for (const j of itemAt(graph.nodes, i).neighbours)
        if (order[j] === -1) {
          order[j] = k++;
          queue.push(j);
        }
    }
  }
  return order;
}

import { clamp, itemAt } from "../chart-utils";
import { enterCurve, r2, type FrameStore } from "../flow-utils";
import type { ChartTipAnchor } from "../heatmap";
import { SPREAD, circlePath, dotScale, nameOffset } from "./layout";
import type { Batches, Graph } from "./model";
import type { GraphRefs, PaintScope } from "./refs";

/** What a frame is painted from: the refs, the graph and its mark batches, the entrance order and the tooltip store. */
export type PaintContext = {
  R: GraphRefs;
  graph: Graph;
  batches: Batches;
  /** Entrance order of each node (breadth first from the most connected). */
  rank: number[];
  n: number;
  tip: FrameStore<ChartTipAnchor>;
};

/** The tooltip's anchor: the active dot, and its name when it has one (the tooltip never covers it). */
export function anchorOf(R: GraphRefs, graph: Graph, i: number): ChartTipAnchor {
  const v = R.viewRef.current;
  const D = R.drawnRef.current;
  const g = itemAt(graph.nodes, i);
  const r = g.r * dotScale(v.k);
  const sx = (D[i * 2] ?? 0) * v.k + v.tx;
  const sy = (D[i * 2 + 1] ?? 0) * v.k + v.ty;
  let x0 = sx - r;
  let x1 = sx + r;
  let y0 = sy - r;
  let y1 = sy + r;
  const nm = R.namesRef.current.find((m) => m.i === i);
  if (nm) {
    const [dx, dy] = nameOffset(nm.side, r);
    const nx = sx + dx;
    const ny = sy + dy;
    const nx0 = nm.side === "right" ? nx : nm.side === "left" ? nx - nm.w : nx - nm.w / 2;
    x0 = Math.min(x0, nx0);
    x1 = Math.max(x1, nx0 + nm.w);
    y0 = Math.min(y0, ny - 7);
    y1 = Math.max(y1, ny + 7);
  }
  return { x: x0, y: R.dockRef.current + y0, w: x1 - x0, h: y1 - y0 };
}

/** A circle mark (the active node's ring, a lit neighbour) placed on node `i`, or hidden when it has no node. */
function place(el: SVGCircleElement, i: number | undefined, r: number, D: Float64Array, U: Float64Array) {
  const u = i === undefined ? NaN : (U[i] ?? 0);
  if (i === undefined || !(u > 0)) {
    el.style.display = "none";
    return;
  }
  el.style.display = "";
  el.setAttribute("cx", String(r2(D[i * 2] ?? 0)));
  el.setAttribute("cy", String(r2(D[i * 2 + 1] ?? 0)));
  el.setAttribute("r", String(r2(r * u * 1e3) / 1e3));
}

/**
 * Paint one frame straight to the SVG: the view transform, the dots (one path per colour) and lines (one path per
 * width) when they move or the zoom changes, the names following their nodes, the active node's ring and the
 * reading's copies, and the tooltip's anchor. `what` says how much changed: everything ("all"), only the view
 * transform ("view") or only the names ("names").
 */
export function paintFrame({ R, graph, batches, rank, n, tip }: PaintContext, what: PaintScope) {
  const P = R.posRef.current;
  const v = R.viewRef.current;
  const m = R.marksRef.current;
  R.viewLayerRef.current?.setAttribute("transform", `translate(${r2(v.tx)},${r2(v.ty)}) scale(${r2(v.k * 1e4) / 1e4})`);
  R.nameLayerRef.current?.setAttribute("transform", `translate(${r2(v.tx)},${r2(v.ty)})`);
  const zoomed = v.k !== R.lastKRef.current;
  const s = dotScale(v.k);
  const D = R.drawnRef.current;
  const U = R.unitRef.current;
  // Dots move (layout, ripple, drag) or keep their screen size through a zoom: rewrite their paths.
  if (what === "all" || zoomed) {
    R.lastKRef.current = v.k;
    const it = R.introRef.current;
    const c = R.centreRef.current;
    for (let i = 0; i < n; i++) {
      const x = P?.[i * 2] ?? NaN;
      const y = P?.[i * 2 + 1] ?? NaN;
      if (!Number.isFinite(x) || !Number.isFinite(y)) {
        D[i * 2] = NaN;
        D[i * 2 + 1] = NaN;
        U[i] = NaN;
        continue;
      }
      // Ripple: node i leaves the centre at its rank's delay.
      const p =
        it >= 1 ? 1 : enterCurve(clamp((it - ((rank[i] ?? 0) / Math.max(1, n - 1)) * SPREAD) / (1 - SPREAD), 0, 1));
      D[i * 2] = c.x + (x - c.x) * p;
      D[i * 2 + 1] = c.y + (y - c.y) * p;
      // Inside the zoomed layer a dot is scaled back to its screen size (times the zoom's growth).
      U[i] = (p * s) / v.k;
    }
    for (const b of batches.nodes) {
      const el = m.nodes.get(b.color);
      if (!el) continue;
      let d = "";
      for (const i of b.idx) d += circlePath(D[i * 2] ?? 0, D[i * 2 + 1] ?? 0, itemAt(graph.nodes, i).r * (U[i] ?? 0));
      el.setAttribute("d", d);
    }
    if (what === "all") {
      // Strokes are non-scaling (vector-effect): lines keep their screen width at any zoom, untouched by it.
      for (const b of batches.links) {
        const el = m.links.get(String(b.w));
        if (!el) continue;
        let d = "";
        for (const l of b.list) {
          const x1 = D[l.s * 2] ?? 0;
          const y1 = D[l.s * 2 + 1] ?? 0;
          const x2 = D[l.t * 2] ?? 0;
          const y2 = D[l.t * 2 + 1] ?? 0;
          if (Number.isFinite(x1 + y1 + x2 + y2)) d += `M${r2(x1)},${r2(y1)}L${r2(x2)},${r2(y2)}`;
        }
        el.setAttribute("d", d);
      }
      const linkIn = clamp((it - 0.55) / 0.45, 0, 1);
      const fade = R.linkFadeRef.current;
      if (fade) fade.style.opacity = linkIn >= 1 ? "" : String(r2(linkIn));
    }
  }
  // Names follow their nodes (screen px inside the panned layer). A pan alone moves only the layer.
  if (what !== "view" || zoomed) {
    for (const nm of R.namesRef.current) {
      const el = m.names.get(String(nm.i));
      const g = graph.nodes[nm.i];
      if (!el || !g) continue;
      const [dx, dy] = nameOffset(nm.side, g.r * s);
      el.setAttribute("x", String(r2((D[nm.i * 2] ?? 0) * v.k + dx)));
      el.setAttribute("y", String(r2((D[nm.i * 2 + 1] ?? 0) * v.k + dy)));
    }
  }
  // The active node's ring, and the reading's copies, sit on the marks they light up (a handful of elements).
  const on = R.activeRef.current;
  const ring = R.ringRef.current;
  if (ring)
    place(
      ring,
      on !== null && on < n ? on : undefined,
      on !== null && on < n ? itemAt(graph.nodes, on).r + 4.5 : 0,
      D,
      U,
    );
  for (const [id, el] of m.litNodes) {
    const i = graph.index.get(id);
    place(el, i, i === undefined ? 0 : itemAt(graph.nodes, i).r + (i === on ? 1.5 : 0), D, U);
  }
  for (const [id, el] of m.litLinks) {
    const l = batches.linkById.get(id);
    const x1 = l ? (D[l.s * 2] ?? 0) : NaN;
    const y1 = l ? (D[l.s * 2 + 1] ?? 0) : NaN;
    const x2 = l ? (D[l.t * 2] ?? 0) : NaN;
    const y2 = l ? (D[l.t * 2 + 1] ?? 0) : NaN;
    if (!Number.isFinite(x1 + y1 + x2 + y2)) {
      el.style.display = "none";
      continue;
    }
    el.style.display = "";
    el.setAttribute("x1", String(r2(x1)));
    el.setAttribute("y1", String(r2(y1)));
    el.setAttribute("x2", String(r2(x2)));
    el.setAttribute("y2", String(r2(y2)));
  }
  // The tooltip follows its node (one transform write, no render).
  const a = R.actRef.current;
  if (a !== null && a < n) tip.setNow(anchorOf(R, graph, a));
}

"use client";

import { createRef, useState, type RefObject } from "react";
import type { Name, View } from "./layout";
import type { ForceSimulation } from "./simulation";

/** What a paint rewrites: every mark ("all"), only the view transform ("view"), or the names ("names"). */
export type PaintScope = "all" | "view" | "names";

/** The pointer gesture in progress: a node being dragged, or the background being panned. */
export type Gesture = {
  kind: "node" | "pan";
  i: number;
  pointerId: number;
  x: number;
  y: number;
  moved: boolean;
  wasActive: boolean;
  touch: boolean;
  view: View;
};

/** A two-finger pinch: the fingers' distance and midpoint when it began, and the view then. */
export type Pinch = { d: number; mx: number; my: number; view: View };

/** The SVG marks the painter writes to, found by `data-id` after each render. */
export type Marks = {
  /** One path per colour holds every dot of that colour; one path per stroke width every line of that width. */
  nodes: Map<string, SVGPathElement>;
  links: Map<string, SVGPathElement>;
  names: Map<string, SVGTextElement>;
  /** The reading's own copies of the active node's ties and neighbours, drawn over the dimmed graph. */
  litNodes: Map<string, SVGCircleElement>;
  litLinks: Map<string, SVGLineElement>;
};

/**
 * What is on screen, kept outside React: the simulation, node positions, the view transform, the running tweens
 * and the SVG layers the painter writes to. One ref each, shared by the hooks in this folder; the object itself
 * never changes, so it is safe in a dependency list.
 */
export type GraphRefs = {
  svgRef: RefObject<SVGSVGElement | null>;
  viewLayerRef: RefObject<SVGGElement | null>;
  linkFadeRef: RefObject<SVGGElement | null>;
  linkLayerRef: RefObject<SVGGElement | null>;
  nodeLayerRef: RefObject<SVGGElement | null>;
  litLinkLayerRef: RefObject<SVGGElement | null>;
  litNodeLayerRef: RefObject<SVGGElement | null>;
  nameLayerRef: RefObject<SVGGElement | null>;
  /** The active node's ring (placed by the painter). */
  ringRef: RefObject<SVGCircleElement | null>;
  reducedRef: RefObject<boolean>;
  simRef: RefObject<ForceSimulation | null>;
  /** Node positions (simulation units) in graph order; NaN = not placed yet (a node new in this data). */
  posRef: RefObject<number[] | null>;
  posIdsRef: RefObject<string[]>;
  /**
   * Where each node is drawn right now (the entrance ripple included), and the scale of its dot inside the zoomed
   * layer (its radius there is r × unit; NaN = not drawn).
   */
  drawnRef: RefObject<Float64Array>;
  unitRef: RefObject<Float64Array>;
  /** Where the layout settled (the glide's target). */
  finalRef: RefObject<number[] | null>;
  centreRef: RefObject<{ x: number; y: number }>;
  viewRef: RefObject<View>;
  /** Entrance progress, 0 to 1. */
  introRef: RefObject<number>;
  glideRef: RefObject<{ stop: () => void } | null>;
  viewTweenRef: RefObject<{ stop: () => void } | null>;
  liveRafRef: RefObject<number>;
  /** The reader has zoomed or panned: a new layout or resize no longer re-fits the view. */
  userMovedRef: RefObject<boolean>;
  marksRef: RefObject<Marks>;
  settleTimerRef: RefObject<number>;
  /** Names placed at the last settle, read by the painter (they follow their nodes while things move). */
  namesRef: RefObject<Name[]>;
  paintRef: RefObject<(what: PaintScope) => void>;
  lastKRef: RefObject<number>;
  /** The reading being drawn (null while a node is dragged), and the active node. */
  actRef: RefObject<number | null>;
  activeRef: RefObject<number | null>;
  dockRef: RefObject<number>;
  paintedGraphRef: RefObject<unknown>;
  fittedForRef: RefObject<string>;
  panOffsetRef: RefObject<{ dx: number; dy: number } | null>;
  gestureRef: RefObject<Gesture | null>;
  touchesRef: RefObject<Map<number, { x: number; y: number }>>;
  pinchRef: RefObject<Pinch | null>;
  /** The latest zoom and hit-test functions, for the non-passive wheel and touch listeners. */
  zoomRef: RefObject<(factor: number, at?: { x: number; y: number }, instant?: boolean) => void>;
  hitRef: RefObject<(x: number, y: number) => boolean>;
};

function createGraphRefs(reduced: boolean): GraphRefs {
  return {
    svgRef: createRef<SVGSVGElement>(),
    viewLayerRef: createRef<SVGGElement>(),
    linkFadeRef: createRef<SVGGElement>(),
    linkLayerRef: createRef<SVGGElement>(),
    nodeLayerRef: createRef<SVGGElement>(),
    litLinkLayerRef: createRef<SVGGElement>(),
    litNodeLayerRef: createRef<SVGGElement>(),
    nameLayerRef: createRef<SVGGElement>(),
    ringRef: createRef<SVGCircleElement>(),
    reducedRef: { current: reduced },
    simRef: { current: null },
    posRef: { current: null },
    posIdsRef: { current: [] },
    drawnRef: { current: new Float64Array(0) },
    unitRef: { current: new Float64Array(0) },
    finalRef: { current: null },
    centreRef: { current: { x: 0, y: 0 } },
    viewRef: { current: { k: 1, tx: 0, ty: 0 } },
    introRef: { current: reduced ? 1 : 0 },
    glideRef: { current: null },
    viewTweenRef: { current: null },
    liveRafRef: { current: 0 },
    userMovedRef: { current: false },
    marksRef: {
      current: { nodes: new Map(), links: new Map(), names: new Map(), litNodes: new Map(), litLinks: new Map() },
    },
    settleTimerRef: { current: 0 },
    namesRef: { current: [] },
    paintRef: { current: () => undefined },
    lastKRef: { current: NaN },
    actRef: { current: null },
    activeRef: { current: null },
    dockRef: { current: 0 },
    paintedGraphRef: { current: null },
    fittedForRef: { current: "" },
    panOffsetRef: { current: null },
    gestureRef: { current: null },
    touchesRef: { current: new Map() },
    pinchRef: { current: null },
    zoomRef: { current: () => undefined },
    hitRef: { current: () => false },
  };
}

/** One stable set of refs per graph instance: created on the first render, the same object after. */
export function useGraphRefs(reduced: boolean): GraphRefs {
  const [refs] = useState(() => createGraphRefs(reduced));
  return refs;
}

/* ======================================================================
 * Force simulation (velocity Verlet, after d3-force): link springs,
 * many-body charge, centring, weak gravity and collision.
 * ====================================================================== */

/**
 * Tuning of the force layout: link length, charge, collision padding, number of ticks, gravity, aspect
 * and the approximation `theta`.
 */
export type ForceSimulationOptions = {
  /** Rest length of a link. Default 38. */
  linkDistance?: number;
  /** Many-body strength: negative repels. Default −110. */
  charge?: number;
  /** Extra space kept between node circles. Default 4. */
  collidePadding?: number;
  /** Ticks for a full cool-down from alpha 1. Default 300. */
  ticks?: number;
  /** Pull towards the centre that keeps unlinked parts close. Default 0.06. */
  gravity?: number;
  /**
   * Width ÷ height of the box the layout will be shown in. Gravity pulls harder across the short
   * side, so a wide card gets a wide layout instead of a small round one. Default 1.
   */
  aspect?: number;
  /**
   * Barnes–Hut accuracy for big graphs (more than 100 nodes): far-away groups of nodes repel as
   * one. Smaller is more exact and slower. Default 0.9 (as d3). Small graphs are always exact.
   */
  theta?: number;
};

/**
 * A running force layout: node positions (`x`, `y`), pinned positions, its energy (`alpha`) and `tick`
 * to advance it.
 */
export type ForceSimulation = {
  readonly x: Float64Array;
  readonly y: Float64Array;
  /** Pinned positions (null = free), e.g. while a node is dragged. */
  fx: (number | null)[];
  fy: (number | null)[];
  alpha: number;
  alphaTarget: number;
  readonly alphaMin: number;
  tick: () => void;
  /** Flat [x0, y0, x1, y1, ...] copy of the positions. */
  positions: () => number[];
};

/** A tiny deterministic nudge for coincident points (d3 uses Math.random; layouts here must repeat exactly). */
export const jiggle = (i: number, j: number) => (((i * 7919 + j * 104_729) % 1000) / 1000 - 0.5) * 1e-6;

/** Above this many nodes, charge uses a Barnes–Hut quadtree and collision a grid (O(n log n), not O(n²)). */
export const EXACT_UP_TO = 100;

/** A cell of the Barnes–Hut quadtree: its square, the centre and mass of its points, and its children. */
export type Quad = {
  x0: number;
  y0: number;
  s: number;
  cx: number;
  cy: number;
  m: number;
  kids: (Quad | null)[] | null;
  pts: number[];
};

/** Creates an empty quadtree cell at `(x0, y0)` with side `s`. */
export const quad = (x0: number, y0: number, s: number): Quad => ({
  x0,
  y0,
  s,
  cx: 0,
  cy: 0,
  m: 0,
  kids: null,
  pts: [],
});

/** Adds point `i` to a cell, splitting the cell when it already holds one. */
export function quadInsert(q: Quad, i: number, depth: number, x: Float64Array, y: Float64Array) {
  if (!q.kids) {
    // A leaf keeps one point (or several that sit on top of each other, past depth 20).
    if (q.pts.length === 0 || depth >= 20) {
      q.pts.push(i);
      return;
    }
    const old = q.pts;
    q.pts = [];
    q.kids = [null, null, null, null];
    for (const j of old) quadChild(q, j, depth, x, y);
  }
  quadChild(q, i, depth, x, y);
}

/** Hands point `i` to the child cell of `q` that contains it, creating the cell when needed. */
export function quadChild(q: Quad, i: number, depth: number, x: Float64Array, y: Float64Array) {
  const h = q.s / 2;
  const right = (x[i] ?? 0) >= q.x0 + h ? 1 : 0;
  const down = (y[i] ?? 0) >= q.y0 + h ? 1 : 0;
  const k = down * 2 + right;
  const kids = (q.kids ??= [null, null, null, null]);
  const c = (kids[k] ??= quad(q.x0 + right * h, q.y0 + down * h, h));
  quadInsert(c, i, depth + 1, x, y);
}

/** Computes the mass and centre of mass of every cell, bottom up. */
export function quadSum(q: Quad, x: Float64Array, y: Float64Array) {
  let m = 0;
  let sx = 0;
  let sy = 0;
  if (q.kids) {
    for (const c of q.kids) {
      if (!c) continue;
      quadSum(c, x, y);
      m += c.m;
      sx += c.cx * c.m;
      sy += c.cy * c.m;
    }
  } else {
    for (const j of q.pts) {
      m += 1;
      sx += x[j] ?? 0;
      sy += y[j] ?? 0;
    }
  }
  q.m = m;
  q.cx = m > 0 ? sx / m : 0;
  q.cy = m > 0 ? sy / m : 0;
}

/** Charge on node i from everything in quad q: far groups act as one body at their centre. */
export function quadRepel(
  q: Quad,
  i: number,
  k: number,
  theta2: number,
  x: Float64Array,
  y: Float64Array,
  vx: Float64Array,
  vy: Float64Array,
) {
  if (q.m === 0) return;
  if (q.kids) {
    const dx = q.cx - (x[i] ?? 0);
    const dy = q.cy - (y[i] ?? 0);
    let l2 = dx * dx + dy * dy;
    if ((q.s * q.s) / theta2 < l2) {
      if (l2 < 1) l2 = Math.sqrt(l2);
      const w = (k * q.m) / l2;
      vx[i] = (vx[i] ?? 0) + dx * w;
      vy[i] = (vy[i] ?? 0) + dy * w;
      return;
    }
    for (const c of q.kids) if (c) quadRepel(c, i, k, theta2, x, y, vx, vy);
    return;
  }
  for (const j of q.pts) {
    if (j === i) continue;
    let dx = (x[j] ?? 0) - (x[i] ?? 0);
    let dy = (y[j] ?? 0) - (y[i] ?? 0);
    let l2 = dx * dx + dy * dy;
    if (l2 === 0) {
      dx = jiggle(i, j);
      dy = jiggle(j, i);
      l2 = dx * dx + dy * dy;
    }
    if (l2 < 1) l2 = Math.sqrt(l2);
    const w = k / l2;
    vx[i] = (vx[i] ?? 0) + dx * w;
    vy[i] = (vy[i] ?? 0) + dy * w;
  }
}

/**
 * Builds a force simulation over `count` nodes of radius `radii`, linked by `links` (indexes).
 * Starting positions default to a phyllotaxis spiral, so the same graph always lays out the same.
 */
export function createForceSimulation(
  radii: readonly number[],
  links: readonly { source: number; target: number }[],
  init: readonly ({ x: number; y: number } | null)[] | null,
  {
    linkDistance = 38,
    charge = -110,
    collidePadding = 4,
    ticks = 300,
    gravity = 0.06,
    aspect = 1,
    theta = 0.9,
  }: ForceSimulationOptions = {},
): ForceSimulation {
  const n = radii.length;
  const x = new Float64Array(n);
  const y = new Float64Array(n);
  const vx = new Float64Array(n);
  const vy = new Float64Array(n);
  const r = Float64Array.from(radii);
  const maxR = r.reduce((m, v) => Math.max(m, v), 0);
  const golden = Math.PI * (3 - Math.sqrt(5));
  for (let i = 0; i < n; i++) {
    const p = init?.[i];
    if (p) {
      x[i] = p.x;
      y[i] = p.y;
    } else {
      const rad = 10 * Math.sqrt(0.5 + i);
      x[i] = rad * Math.cos(i * golden);
      y[i] = rad * Math.sin(i * golden);
    }
  }
  const degree = new Array<number>(n).fill(0);
  for (const l of links) {
    degree[l.source] = (degree[l.source] ?? 0) + 1;
    degree[l.target] = (degree[l.target] ?? 0) + 1;
  }
  const springs = links.map((l) => {
    const ds = degree[l.source] ?? 1;
    const dt = degree[l.target] ?? 1;
    return {
      s: l.source,
      t: l.target,
      strength: 1 / Math.max(1, Math.min(ds, dt)),
      bias: ds / Math.max(1, ds + dt),
      distance: linkDistance + (r[l.source] ?? 0) + (r[l.target] ?? 0),
    };
  });
  const stretch = Math.sqrt(Math.min(4, Math.max(0.25, aspect)));
  const gx = gravity / stretch;
  const gy = gravity * stretch;
  const alphaMin = 0.001;
  const alphaDecay = 1 - alphaMin ** (1 / Math.max(1, ticks));
  const velocityDecay = 0.4;
  const theta2 = Math.max(0.01, theta * theta);
  const exact = n <= EXACT_UP_TO;

  const collide = (i: number, j: number) => {
    let dx = (x[i] ?? 0) + (vx[i] ?? 0) - (x[j] ?? 0) - (vx[j] ?? 0);
    let dy = (y[i] ?? 0) + (vy[i] ?? 0) - (y[j] ?? 0) - (vy[j] ?? 0);
    const rr = (r[i] ?? 0) + (r[j] ?? 0) + collidePadding;
    let l2 = dx * dx + dy * dy;
    if (l2 >= rr * rr) return;
    if (l2 === 0) {
      dx = jiggle(i, j);
      dy = jiggle(j, i);
      l2 = dx * dx + dy * dy;
    }
    const l = Math.sqrt(l2);
    const k = ((rr - l) / l) * 0.7;
    dx *= k;
    dy *= k;
    const ri2 = (r[i] ?? 0) * (r[i] ?? 0);
    const rj2 = (r[j] ?? 0) * (r[j] ?? 0);
    const wi = rj2 / Math.max(1e-9, ri2 + rj2);
    vx[i] = (vx[i] ?? 0) + dx * wi;
    vy[i] = (vy[i] ?? 0) + dy * wi;
    vx[j] = (vx[j] ?? 0) - dx * (1 - wi);
    vy[j] = (vy[j] ?? 0) - dy * (1 - wi);
  };

  const sim: ForceSimulation = {
    x,
    y,
    fx: new Array<number | null>(n).fill(null),
    fy: new Array<number | null>(n).fill(null),
    alpha: 1,
    alphaTarget: 0,
    alphaMin,
    positions: () => {
      const out = new Array<number>(n * 2);
      for (let i = 0; i < n; i++) {
        out[i * 2] = x[i] ?? 0;
        out[i * 2 + 1] = y[i] ?? 0;
      }
      return out;
    },
    tick: () => {
      sim.alpha += (sim.alphaTarget - sim.alpha) * alphaDecay;
      const a = sim.alpha;
      // Links: springs towards their rest length, the lighter end moving more.
      for (const l of springs) {
        let dx = (x[l.t] ?? 0) + (vx[l.t] ?? 0) - (x[l.s] ?? 0) - (vx[l.s] ?? 0);
        let dy = (y[l.t] ?? 0) + (vy[l.t] ?? 0) - (y[l.s] ?? 0) - (vy[l.s] ?? 0);
        if (dx === 0) dx = jiggle(l.s, l.t);
        if (dy === 0) dy = jiggle(l.t, l.s);
        const len = Math.sqrt(dx * dx + dy * dy);
        const k = ((len - l.distance) / len) * a * l.strength;
        dx *= k;
        dy *= k;
        vx[l.t] = (vx[l.t] ?? 0) - dx * l.bias;
        vy[l.t] = (vy[l.t] ?? 0) - dy * l.bias;
        vx[l.s] = (vx[l.s] ?? 0) + dx * (1 - l.bias);
        vy[l.s] = (vy[l.s] ?? 0) + dy * (1 - l.bias);
      }
      // Charge: the exact pairwise sum for small graphs, Barnes–Hut for big ones.
      if (exact) {
        for (let i = 0; i < n; i++) {
          for (let j = i + 1; j < n; j++) {
            let dx = (x[j] ?? 0) - (x[i] ?? 0);
            let dy = (y[j] ?? 0) - (y[i] ?? 0);
            let l2 = dx * dx + dy * dy;
            if (l2 === 0) {
              dx = jiggle(i, j);
              dy = jiggle(j, i);
              l2 = dx * dx + dy * dy;
            }
            if (l2 < 1) l2 = Math.sqrt(l2);
            const w = (charge * a) / l2;
            vx[i] = (vx[i] ?? 0) + dx * w;
            vy[i] = (vy[i] ?? 0) + dy * w;
            vx[j] = (vx[j] ?? 0) - dx * w;
            vy[j] = (vy[j] ?? 0) - dy * w;
          }
        }
      } else if (n > 0) {
        let x0 = Infinity;
        let y0 = Infinity;
        let x1 = -Infinity;
        let y1 = -Infinity;
        for (let i = 0; i < n; i++) {
          x0 = Math.min(x0, x[i] ?? 0);
          x1 = Math.max(x1, x[i] ?? 0);
          y0 = Math.min(y0, y[i] ?? 0);
          y1 = Math.max(y1, y[i] ?? 0);
        }
        const root = quad(x0, y0, Math.max(1, x1 - x0, y1 - y0) * 1.0001);
        for (let i = 0; i < n; i++) quadInsert(root, i, 0, x, y);
        quadSum(root, x, y);
        const k = charge * a;
        for (let i = 0; i < n; i++) quadRepel(root, i, k, theta2, x, y, vx, vy);
      }
      // Gravity, then keep the centre of mass at the origin.
      let mx = 0;
      let my = 0;
      for (let i = 0; i < n; i++) {
        vx[i] = (vx[i] ?? 0) - (x[i] ?? 0) * gx * a;
        vy[i] = (vy[i] ?? 0) - (y[i] ?? 0) * gy * a;
        mx += x[i] ?? 0;
        my += y[i] ?? 0;
      }
      if (n > 0 && sim.fx.every((v) => v === null)) {
        mx /= n;
        my /= n;
        for (let i = 0; i < n; i++) {
          x[i] = (x[i] ?? 0) - mx;
          y[i] = (y[i] ?? 0) - my;
        }
      }
      // Collision: every pair for small graphs; neighbouring grid cells for big ones.
      if (exact) {
        for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) collide(i, j);
      } else {
        const cell = Math.max(1, maxR * 2 + collidePadding);
        const grid = new Map<number, number[]>();
        const keyOf = (gx: number, gy: number) => (gx + 32_768) * 65_536 + (gy + 32_768);
        const cx = new Int32Array(n);
        const cy = new Int32Array(n);
        for (let i = 0; i < n; i++) {
          cx[i] = Math.floor(((x[i] ?? 0) + (vx[i] ?? 0)) / cell);
          cy[i] = Math.floor(((y[i] ?? 0) + (vy[i] ?? 0)) / cell);
          const key = keyOf(cx[i] ?? 0, cy[i] ?? 0);
          const list = grid.get(key);
          if (list) list.push(i);
          else grid.set(key, [i]);
        }
        for (let i = 0; i < n; i++) {
          for (let gx = (cx[i] ?? 0) - 1; gx <= (cx[i] ?? 0) + 1; gx++)
            for (let gy = (cy[i] ?? 0) - 1; gy <= (cy[i] ?? 0) + 1; gy++) {
              const list = grid.get(keyOf(gx, gy));
              if (list) for (const j of list) if (j > i) collide(i, j);
            }
        }
      }
      // Integrate.
      for (let i = 0; i < n; i++) {
        const px = sim.fx[i];
        const py = sim.fy[i];
        if (px !== null && px !== undefined) {
          x[i] = px;
          vx[i] = 0;
        } else {
          vx[i] = (vx[i] ?? 0) * (1 - velocityDecay);
          x[i] = (x[i] ?? 0) + (vx[i] ?? 0);
        }
        if (py !== null && py !== undefined) {
          y[i] = py;
          vy[i] = 0;
        } else {
          vy[i] = (vy[i] ?? 0) * (1 - velocityDecay);
          y[i] = (y[i] ?? 0) + (vy[i] ?? 0);
        }
      }
    },
  };
  return sim;
}

import { type ReactNode } from "react";
import { itemAt } from "../chart-utils";
import { ChartValueTable, defaultCompact } from "../heatmap";
import { buildGraph } from "./model";
import { type NetworkGraphProps } from "./types";

/* ---------- Table view (the keyboard list of every node) ---------- */

/**
 * Props of NetworkTable, the table view of the chart: the chart's data and formatting props plus a
 * hidden `caption` for screen readers.
 */
export type NetworkTableProps = Pick<NetworkGraphProps, "nodes" | "links" | "groups" | "format" | "locale"> & {
  /** Hidden caption that names the table for screen readers. */
  caption?: string;
  /** Override the column headers: { node, group, connections, value, linked }. */
  headers?: Partial<{ node: string; group: string; connections: string; value: string; linked: string }>;
  /** Shown when there are no rows. */
  emptyState?: ReactNode;
};

/**
 * Every node with its group, its number of connections and who it connects to.
 *
 * Props: the graph's `nodes`, `links`, `groups`, `format` and `locale`, plus `caption` (hidden, names the table), `headers` ({ node, group, connections, value, linked }) and `emptyState`. A real table: every node with its group, its number of connections and who it connects to. Static (no motion). Pass it to `ChartCard table`.
 *
 * @example
 * ```tsx
 * import { NetworkTable } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <NetworkTable nodes={[{ id: "api" }, { id: "db" }]} links={[{ source: "api", target: "db" }]} caption="Service dependencies" />
 *   );
 * }
 * ```
 *
 * @see /charts/network-graph
 */
export function NetworkTable({
  nodes,
  links,
  groups,
  format: formatProp,
  locale,
  caption,
  headers,
  emptyState,
}: NetworkTableProps) {
  const format = formatProp ?? defaultCompact(locale);
  const h = {
    node: "Node",
    group: "Group",
    connections: "Connections",
    value: "Value",
    linked: "Connected to",
    ...headers,
  };
  const graph = buildGraph(nodes, links, groups);
  const hasGroups = graph.nodes.some((g) => g.groupLabel);
  const hasValues = graph.nodes.some((g) => g.value !== null);
  return (
    <ChartValueTable
      caption={caption}
      emptyState={emptyState}
      columns={[
        { label: h.node },
        ...(hasGroups ? [{ label: h.group, align: "start" as const }] : []),
        { label: h.connections },
        ...(hasValues ? [{ label: h.value }] : []),
        { label: h.linked, align: "start" as const },
      ]}
      rows={graph.nodes.map((g) => [
        g.label,
        ...(hasGroups ? [g.groupLabel ?? ""] : []),
        format(g.neighbours.length),
        ...(hasValues ? [g.value === null ? "" : format(g.value)] : []),
        // A readable paragraph, not a sliver: the column keeps 12rem on phones and the table scrolls sideways.
        <span className="inline-block min-w-48 whitespace-normal text-sheen-fg-muted">
          {g.neighbours.map((j) => itemAt(graph.nodes, j).label).join(", ")}
        </span>,
      ])}
    />
  );
}

import { type ReactNode } from "react";
import { type LegendItem } from "../chart-parts";
import { slotColor, type ChartInstructions } from "../chart-utils";
import { type ForceSimulationOptions } from "./simulation";
import { type NetworkNode, type NetworkLink, type NetworkGroup } from "./model";

/* ======================================================================
 * Component
 * ====================================================================== */

/**
 * Every string NetworkGraph speaks or shows, so it can be translated: pass a `Partial` as the `labels`
 * prop. Entries that need a value are functions.
 */
export type NetworkGraphLabels = {
  roleDescription: string;
  instructions: ChartInstructions;
  hint: string;
  /** "4 connections" (the count is shown as the value). */
  connections: (count: number) => string;
  /** Tooltip row of a node's value. */
  value: string;
  /** Announced after a node's values. */
  connectedTo: (names: string[], more: number) => string;
  zoomIn: string;
  zoomOut: string;
  fit: string;
  /** Accessible name of the zoom toolbar. */
  zoomControls: string;
};

/**
 * The built-in English strings of NetworkGraph; spread it into your own `labels` and change what you
 * need. This module is a client module, so use it from client code, not from a Server Component.
 */
export const defaultNetworkGraphLabels: NetworkGraphLabels = {
  roleDescription: "network graph",
  instructions:
    "Use the arrow keys to move to the nearest node in that direction, Page Up and Page Down to step through every node in order, plus and minus to zoom and 0 to fit. Drag a node to move it; Ctrl or Command and scroll to zoom.",
  hint: "Tap a node to see its connections",
  connections: (count) => (count === 1 ? "connection" : "connections"),
  value: "value",
  connectedTo: (names, more) => `Connected to ${names.join(", ")}${more > 0 ? ` and ${more} more` : ""}`,
  zoomIn: "Zoom in",
  zoomOut: "Zoom out",
  fit: "Fit to view",
  zoomControls: "Zoom",
};

/**
 * Props of NetworkGraph. The component's own doc comment describes its behaviour, keyboard use and
 * accessibility.
 */
export type NetworkGraphProps = {
  /** The nodes: { id, label?, group?, value? }. `value` sizes the dot. */
  nodes: readonly NetworkNode[];
  /** Ties between nodes (undirected). Repeated pairs add up; links to unknown ids are left out. */
  links: readonly NetworkLink[];
  /** Names and colour slots of the groups. Groups only named on nodes get the next free slot. */
  groups?: readonly NetworkGroup[];
  /** Height of the chart in px; the width follows the container. Default 420. */
  height?: number;
  /** Which names to print: where they fit without colliding ("auto", default), all, or none. */
  showLabels?: "auto" | "all" | "none";
  /** Sets the tuning of the force layout. */
  forces?: ForceSimulationOptions;
  /** Formats node values. Default compact numbers in `locale`. */
  format?: (n: number) => string;
  /** Locale of the default number format. Default "en". */
  locale?: string;
  /** Called with { id, label, group, connections } when a node is clicked, tapped, or activated with Enter. */
  onNodeClick?: (node: { id: string; label: string; group: string | null; connections: string[] }) => void;
  /** Shown when there is nothing to plot. */
  emptyState?: ReactNode;
  /** Override the chart's strings (i18n). */
  labels?: Partial<NetworkGraphLabels>;
  /** Names the chart for assistive tech (required). */
  "aria-label": string;
  /** Adds extra classes to the outer element. */
  className?: string;
};

/** Legend items for a network graph's groups (pass to ChartCard's `legend`). */
export function networkLegend(groups: readonly NetworkGroup[]): LegendItem[] {
  return groups.map((g, i) => ({
    label: g.label ?? g.id,
    color: slotColor(g.color ?? (i < 8 ? i + 1 : 0)),
    kind: "rect" as const,
  }));
}

"use client";

import { useEffect, type Dispatch, type SetStateAction } from "react";
import { animate } from "motion/react";
import { INTRO } from "./layout";
import type { GraphRefs } from "./refs";

/** What the entrance needs: the refs, whether the chart may play, has a layout, and has already played. */
export type EntranceInput = {
  R: GraphRefs;
  play: boolean;
  hasLayout: boolean;
  introDone: boolean;
  reduced: boolean;
  setIntroDone: Dispatch<SetStateAction<boolean>>;
};

/**
 * The entrance: nodes ripple out from the centre (by breadth-first rank), then the links draw in; one tween, painted
 * by the painter. Reduced motion shows the layout in place at once.
 */
export function useGraphEntrance({ R, play, hasLayout, introDone, reduced, setIntroDone }: EntranceInput) {
  const { introRef, paintRef, reducedRef } = R;
  useEffect(() => {
    if (introDone || !play || !hasLayout) return;
    if (reducedRef.current) {
      introRef.current = 1;
      paintRef.current("all");
      setIntroDone(true);
      return;
    }
    const start = introRef.current;
    const controls = animate(start, 1, {
      duration: INTRO * (1 - start),
      ease: "linear",
      onUpdate: (v) => {
        introRef.current = v;
        paintRef.current("all");
      },
      onComplete: () => setIntroDone(true),
    });
    return () => controls.stop();
  }, [play, hasLayout, introDone, introRef, paintRef, reducedRef, setIntroDone]);
  useEffect(() => {
    if (!reduced) return;
    introRef.current = 1;
    paintRef.current("all");
  }, [reduced, introRef, paintRef]);
}

"use client";

import { useEffect, type Dispatch, type PointerEvent, type SetStateAction } from "react";
import { useSyncRef } from "../../hooks/use-latest";
import { clamp, itemAt } from "../chart-utils";
import { r2 } from "../flow-utils";
import { K_MAX, K_MIN, dotScale, type View } from "./layout";
import type { Graph } from "./model";
import type { GraphRefs } from "./refs";
import type { NetworkGraphProps } from "./types";

/** What the pointer handling needs: the refs, the graph, the reading state and the view's helpers. */
export type GesturesInput = {
  R: GraphRefs;
  graph: Graph;
  n: number;
  act: number | null;
  source: "keyboard" | "pointer";
  hasWidth: boolean;
  onNodeClick: NetworkGraphProps["onNodeClick"];
  setActive: Dispatch<SetStateAction<number | null>>;
  setSource: Dispatch<SetStateAction<"keyboard" | "pointer">>;
  setDragging: Dispatch<SetStateAction<number | null>>;
  setPanning: Dispatch<SetStateAction<boolean>>;
  settle: () => void;
  startLive: () => void;
  setView: (v: View) => void;
  zoomBy: (factor: number, at?: { x: number; y: number }, instant?: boolean) => void;
  screenOf: (i: number) => { x: number; y: number };
  toSim: (sx: number, sy: number) => { x: number; y: number };
};

/**
 * Pointer interaction: hover reads a node, a drag pulls it (the network follows through the live simulation), the
 * background pans on the compositor, two fingers pinch and Ctrl / ⌘ + wheel zooms. Hit testing is done in JS (the
 * nearest dot within reach), so the browser never walks every shape on a mouse move. Returns the SVG's pointer
 * handlers and `move`, which sets the active node and how it was chosen.
 */
export function useGraphGestures({
  R,
  graph,
  n,
  act,
  source,
  hasWidth,
  onNodeClick,
  setActive,
  setSource,
  setDragging,
  setPanning,
  settle,
  startLive,
  setView,
  zoomBy,
  screenOf,
  toSim,
}: GesturesInput) {
  const {
    svgRef,
    viewRef,
    viewTweenRef,
    userMovedRef,
    panOffsetRef,
    paintRef,
    gestureRef,
    touchesRef,
    pinchRef,
    simRef,
    posRef,
    finalRef,
    glideRef,
  } = R;
  const { reducedRef, zoomRef, hitRef } = R;

  // Relative to the svg's (never moved) parent: while a pan slides the svg itself, this box stays put.
  const local = (e: { clientX: number; clientY: number }) => {
    const box = svgRef.current?.parentElement?.getBoundingClientRect();
    return box ? { x: e.clientX - box.left, y: e.clientY - box.top } : { x: 0, y: 0 };
  };

  /* ---------- Panning on the compositor ---------- */

  // While the background is dragged the drawing itself doesn't change: the svg slides as one
  // composited layer (a CSS translate, no repaint, no re-raster), and the offset is folded into
  // the view when the pan ends. Big graphs pan as smoothly as small ones, on phones too.
  function panTo(dx: number, dy: number) {
    const svg = svgRef.current;
    if (!svg) return;
    if (!panOffsetRef.current) svg.style.willChange = "transform";
    panOffsetRef.current = { dx, dy };
    svg.style.transform = `translate3d(${r2(dx)}px, ${r2(dy)}px, 0)`;
  }
  function endPan() {
    const o = panOffsetRef.current;
    const svg = svgRef.current;
    panOffsetRef.current = null;
    if (!o || !svg) return;
    const v = viewRef.current;
    viewRef.current = { k: v.k, tx: v.tx + o.dx, ty: v.ty + o.dy };
    svg.style.transform = "";
    svg.style.willChange = "";
    paintRef.current("view");
  }
  const nearest = (x: number, y: number, max: number) => {
    let best: number | null = null;
    let bestD = max * max;
    const s = dotScale(viewRef.current.k);
    for (let i = 0; i < n; i++) {
      const p = screenOf(i);
      if (!Number.isFinite(p.x) || !Number.isFinite(p.y)) continue;
      const r = itemAt(graph.nodes, i).r * s;
      const d = (p.x - x) ** 2 + (p.y - y) ** 2 - r * r;
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    return best;
  };

  /* ---------- Interaction ---------- */

  function move(i: number | null, from: "keyboard" | "pointer") {
    setSource(from);
    setActive(i);
  }

  function onPointerDown(event: PointerEvent<SVGSVGElement>) {
    if (event.button !== 0 && event.pointerType === "mouse") return;
    const p = local(event);
    const touch = event.pointerType !== "mouse";
    if (touch) touchesRef.current.set(event.pointerId, p);
    if (touch && touchesRef.current.size === 2) {
      // Second finger: a pinch replaces whatever the first finger started.
      const [a, b] = [...touchesRef.current.values()];
      if (a && b)
        pinchRef.current = {
          d: Math.hypot(a.x - b.x, a.y - b.y),
          mx: (a.x + b.x) / 2,
          my: (a.y + b.y) / 2,
          view: viewRef.current,
        };
      gestureRef.current = null;
      setDragging(null);
      return;
    }
    const hit = nearest(p.x, p.y, touch ? 26 : 14);
    if (hit !== null) {
      gestureRef.current = {
        kind: "node",
        i: hit,
        pointerId: event.pointerId,
        x: p.x,
        y: p.y,
        moved: false,
        wasActive: act === hit,
        touch,
        view: viewRef.current,
      };
      event.currentTarget.setPointerCapture(event.pointerId);
      if (touch) move(hit, "pointer");
    } else {
      // One finger on the background scrolls the page; tapping it clears the reading.
      setActive(null);
      if (touch) return;
      gestureRef.current = {
        kind: "pan",
        i: -1,
        pointerId: event.pointerId,
        x: p.x,
        y: p.y,
        moved: false,
        wasActive: false,
        touch,
        view: viewRef.current,
      };
      event.currentTarget.setPointerCapture(event.pointerId);
    }
  }

  function onPointerMove(event: PointerEvent<SVGSVGElement>) {
    const p = local(event);
    if (event.pointerType !== "mouse" && touchesRef.current.has(event.pointerId))
      touchesRef.current.set(event.pointerId, p);
    if (pinchRef.current && touchesRef.current.size >= 2) {
      const [a, b] = [...touchesRef.current.values()];
      if (!a || !b) return;
      const d = Math.hypot(a.x - b.x, a.y - b.y);
      const mx = (a.x + b.x) / 2;
      const my = (a.y + b.y) / 2;
      const s = pinchRef.current;
      const k = clamp((s.view.k * d) / Math.max(1, s.d), K_MIN, K_MAX);
      // Keep the point under the fingers' midpoint there, and follow the midpoint.
      const cx = (s.mx - s.view.tx) / s.view.k;
      const cy = (s.my - s.view.ty) / s.view.k;
      userMovedRef.current = true;
      viewTweenRef.current?.stop();
      setView({ k, tx: mx - cx * k, ty: my - cy * k });
      settle();
      return;
    }
    const g = gestureRef.current;
    if (!g) {
      if (event.pointerType === "mouse") {
        const hit = nearest(p.x, p.y, 14);
        if (hit !== act || source !== "pointer") move(hit, "pointer");
      }
      return;
    }
    if (g.pointerId !== event.pointerId) return;
    const dist = Math.hypot(p.x - g.x, p.y - g.y);
    if (!g.moved && dist < 3) return;
    const firstMove = !g.moved;
    g.moved = true;
    if (g.kind === "pan") {
      if (firstMove) {
        setPanning(true);
        viewTweenRef.current?.stop();
      }
      userMovedRef.current = true;
      panTo(p.x - g.x, p.y - g.y);
      return;
    }
    // Dragging a node: pin it under the pointer and let the network follow.
    const sim = simRef.current;
    const P = posRef.current;
    if (!sim || !P) return;
    if (firstMove) {
      glideRef.current?.stop();
      setDragging(g.i);
      if (act !== g.i) move(g.i, "pointer");
    }
    const q = toSim(p.x, p.y);
    if (reducedRef.current) {
      // No simulation: only this node moves.
      sim.x[g.i] = q.x;
      sim.y[g.i] = q.y;
      const next = [...P];
      next[g.i * 2] = q.x;
      next[g.i * 2 + 1] = q.y;
      finalRef.current = next;
      posRef.current = next;
      paintRef.current("all");
      return;
    }
    sim.fx[g.i] = q.x;
    sim.fy[g.i] = q.y;
    sim.alphaTarget = 0.3;
    if (sim.alpha < 0.3) sim.alpha = 0.3;
    startLive();
  }

  function onPointerUp(event: PointerEvent<SVGSVGElement>) {
    touchesRef.current.delete(event.pointerId);
    if (touchesRef.current.size < 2) pinchRef.current = null;
    const g = gestureRef.current;
    if (g?.pointerId !== event.pointerId) return;
    gestureRef.current = null;
    if (g.kind === "pan") {
      if (g.moved) {
        endPan();
        setPanning(false);
        settle();
      }
      return;
    }
    const sim = simRef.current;
    if (g.moved) {
      if (sim) {
        sim.fx[g.i] = null;
        sim.fy[g.i] = null;
        sim.alphaTarget = 0;
      }
      setDragging(null);
      if (reducedRef.current) settle();
      return;
    }
    // A tap: the first one on touch reads the node, the next one activates it.
    if (g.touch && !g.wasActive) return;
    const node = itemAt(graph.nodes, g.i);
    onNodeClick?.({
      id: node.id,
      label: node.label,
      group: node.group,
      connections: node.neighbours.map((j) => itemAt(graph.nodes, j).id),
    });
  }

  function onPointerCancel(event: PointerEvent<SVGSVGElement>) {
    touchesRef.current.delete(event.pointerId);
    pinchRef.current = null;
    endPan();
    const g = gestureRef.current;
    if (g?.kind === "node" && g.moved && simRef.current) {
      simRef.current.fx[g.i] = null;
      simRef.current.fy[g.i] = null;
      simRef.current.alphaTarget = 0;
    }
    gestureRef.current = null;
    setDragging(null);
    setPanning(false);
    settle();
  }

  // Ctrl / ⌘ + wheel (and trackpad pinch) zooms; a plain wheel keeps scrolling the page.
  // Touch: a finger that lands on a node drags it, two fingers pinch; one finger on the
  // background still scrolls the page. (touch-action isn't honoured on SVG children, so the
  // touchstart that begins a drag or a pinch is cancelled instead.)
  useSyncRef(zoomRef, zoomBy);
  useSyncRef(hitRef, (x, y) => nearest(x, y, 26) !== null);
  const hasNodes = n > 0;
  useEffect(() => {
    const svg = svgRef.current;
    if (!svg) return;
    const onWheel = (e: WheelEvent) => {
      if (!e.ctrlKey && !e.metaKey) return;
      e.preventDefault();
      const box = (svg.parentElement ?? svg).getBoundingClientRect();
      zoomRef.current(Math.exp(-e.deltaY * 0.01), { x: e.clientX - box.left, y: e.clientY - box.top }, true);
    };
    const onTouchStart = (e: TouchEvent) => {
      if (!e.cancelable) return;
      const t = e.touches[0];
      if (e.touches.length >= 2) e.preventDefault();
      else if (t) {
        const box = (svg.parentElement ?? svg).getBoundingClientRect();
        if (hitRef.current(t.clientX - box.left, t.clientY - box.top)) e.preventDefault();
      }
    };
    svg.addEventListener("wheel", onWheel, { passive: false });
    svg.addEventListener("touchstart", onTouchStart, { passive: false });
    return () => {
      svg.removeEventListener("wheel", onWheel);
      svg.removeEventListener("touchstart", onTouchStart);
    };
  }, [hasWidth, hasNodes, svgRef, zoomRef, hitRef]);

  return { onPointerDown, onPointerMove, onPointerUp, onPointerCancel, move };
}

"use client";

import { useEffectEvent, useLayoutEffect, useState } from "react";
import { itemAt } from "../chart-utils";
import { measureText, type FrameStore } from "../flow-utils";
import type { ChartTipAnchor } from "../heatmap";
import { dotScale, nameOffset, type Name } from "./layout";
import type { Graph } from "./model";
import type { GraphRefs } from "./refs";
import type { NetworkGraphProps } from "./types";

/** What the names need: the refs, the graph, the reading, the box, and the triggers that place them again. */
export type NamesInput = {
  R: GraphRefs;
  graph: Graph;
  act: number | null;
  /** The active node and its neighbours. */
  lit: Set<number>;
  dragging: number | null;
  introDone: boolean;
  showLabels: NonNullable<NetworkGraphProps["showLabels"]>;
  width: number;
  height: number;
  /** Height of the docked readout above the plot. */
  dock: number;
  coarse: boolean;
  /** Re-place triggers: motion settled, a layout landed, web fonts arrived (widths change). */
  settled: number;
  layoutVersion: number;
  fonts: boolean;
  tip: FrameStore<ChartTipAnchor>;
  screenOf: (i: number) => { x: number; y: number };
  anchorOf: (i: number) => ChartTipAnchor;
};

/**
 * Names: placed when the view settles (the active node and its neighbours first, then the best connected; none may
 * collide with a dot, another name or the zoom toolbar), from the node positions and view held in refs, and stored
 * in state so the chart draws them. Also moves the tooltip to its node after each commit. Returns the placed names.
 */
export function useGraphNames({
  R,
  graph,
  act,
  lit,
  dragging,
  introDone,
  showLabels,
  width,
  height,
  dock,
  coarse,
  settled,
  layoutVersion,
  fonts,
  tip,
  screenOf,
  anchorOf,
}: NamesInput) {
  const { posRef, viewRef, namesRef } = R;
  // The labels are placed after the commit, from the node positions and view held in refs (a render
  // never reads them), and stored in state so the chart draws them in a layout effect pass.
  const [names, setNames] = useState<Name[]>([]);
  // `fonts`, `layoutVersion` and `settled` are re-place triggers: widths change when web fonts load and layouts advance.
  // The tooltip follows its node: the anchor comes from the simulation's positions (held in refs), so it is
  // written to the tooltip's store after the commit, never read during render.
  const moveTip = useEffectEvent((node: number) => tip.setNow(anchorOf(node)));
  useLayoutEffect(() => {
    if (act !== null && dragging === null) moveTip(act);
  }, [act, dragging, width, height, dock, introDone, settled, layoutVersion, names]);
  useLayoutEffect(() => {
    const next = (() => {
      const placed: Name[] = [];
      if (!introDone || showLabels === "none" || width === 0 || !posRef.current) return placed;
      const v = viewRef.current;
      const s = dotScale(v.k);
      const boxes: { x0: number; y0: number; x1: number; y1: number }[] = [];
      const circles = graph.nodes.map((g, i) => ({ ...screenOf(i), r: g.r * s }));
      const order = [...graph.nodes].sort((a, b) => {
        const pa = a.index === act ? 0 : lit.has(a.index) ? 1 : 2;
        const pb = b.index === act ? 0 : lit.has(b.index) ? 1 : 2;
        return (
          pa - pb || b.neighbours.length - a.neighbours.length || (b.value ?? 0) - (a.value ?? 0) || a.index - b.index
        );
      });
      // The zoom toolbar in the top right corner: no name goes under it.
      const tool = coarse ? 48 : 36;
      const toolbar = { x0: width - 8 - tool - 4, y0: 4, x1: width, y1: 8 + tool * 3 - 8 + 4 };
      const free = (box: { x0: number; y0: number; x1: number; y1: number }, own: number) =>
        box.x0 >= 0 &&
        box.x1 <= width - 2 &&
        box.y0 >= 0 &&
        box.y1 <= height &&
        !(box.x0 < toolbar.x1 && box.x1 > toolbar.x0 && box.y0 < toolbar.y1 && box.y1 > toolbar.y0) &&
        (showLabels === "all" ||
          (!boxes.some((b) => box.x0 < b.x1 && box.x1 > b.x0 && box.y0 < b.y1 && box.y1 > b.y0) &&
            !circles.some(
              (o, j) =>
                j !== own && o.x + o.r > box.x0 && o.x - o.r < box.x1 && o.y + o.r > box.y0 && o.y - o.r < box.y1,
            )));
      for (const g of order) {
        const c = itemAt(circles, g.index);
        if (!Number.isFinite(c.x) || !Number.isFinite(c.y)) continue;
        const w = measureText(g.label, 11, 500);
        // Right of the dot, then left, below and above: the first spot that's free.
        for (const side of ["right", "left", "below", "above"] as const) {
          const [dx, dy] = nameOffset(side, c.r);
          const x = c.x + dx;
          const y = c.y + dy;
          const x0 = side === "right" ? x - 1 : side === "left" ? x - w - 1 : x - w / 2 - 1;
          const box = { x0, y0: y - 7, x1: x0 + w + 2, y1: y + 7 };
          if (!free(box, g.index)) continue;
          boxes.push(box);
          placed.push({ i: g.index, side, text: g.label, w });
          break;
        }
      }
      return placed;
    })();
    setNames((prev) =>
      prev.length === next.length &&
      prev.every((p, k) => p.i === itemAt(next, k).i && p.side === itemAt(next, k).side && p.w === itemAt(next, k).w)
        ? prev
        : next,
    );
    // `screenOf` is a fresh closure every render over the same refs; the placement re-runs on the triggers below, not on every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps -- names are re-placed when the entrance, labels mode, box, data, reading, pointer type, settle, layout or fonts change, not for a new render's `screenOf`
  }, [introDone, showLabels, width, height, graph, act, lit, coarse, settled, layoutVersion, fonts, posRef, viewRef]);
  // The painter's own layout effect (declared first) ran before this commit's names reached the ref, so the new <text>
  // marks would sit at the origin (piled in the middle) until the next layout frame: hand them over, then paint them.
  useLayoutEffect(() => {
    namesRef.current = names;
    R.paintRef.current("names");
  }, [names, namesRef, R.paintRef]);

  return names;
}

"use client";

import { useLayoutEffect } from "react";
import { useSyncRef } from "../../hooks/use-latest";
import { marksById, type FrameStore } from "../flow-utils";
import type { ChartTipAnchor } from "../heatmap";
import type { Batches, Graph } from "./model";
import { anchorOf, paintFrame } from "./paint";
import type { GraphRefs } from "./refs";

/** What the painter needs: the refs, the graph and its mark batches, the entrance order and the tooltip store. */
export type PainterInput = {
  R: GraphRefs;
  graph: Graph;
  batches: Batches;
  /** Entrance order of each node (breadth first from the most connected). */
  rank: number[];
  n: number;
  ids: string[];
  tip: FrameStore<ChartTipAnchor>;
  act: number | null;
  dragging: number | null;
};

/**
 * Wires the painter (see `paint.ts`): keeps the latest frame painter in a ref for the tweens and handlers, re-indexes
 * what is on screen when the data changes, and after every render finds the marks React drew and paints them where
 * they are now. Returns `anchorOf`, the tooltip's anchor for a node.
 */
export function usePainter({ R, graph, batches, rank, n, ids, tip, act, dragging }: PainterInput) {
  const { posRef, posIdsRef, drawnRef, unitRef, marksRef, paintRef, lastKRef, actRef, activeRef, paintedGraphRef } = R;
  const { nodeLayerRef, linkLayerRef, nameLayerRef, litNodeLayerRef, litLinkLayerRef } = R;

  useSyncRef(actRef, dragging === null ? act : null);
  useSyncRef(activeRef, act);
  useSyncRef(paintRef, (what) => paintFrame({ R, graph, batches, rank, n, tip }, what));

  // A new data set: what is on screen is re-indexed to the new node order (known nodes keep their
  // place, new ones wait for the layout). Runs before the paint below.
  useLayoutEffect(() => {
    const P = posRef.current;
    if (P && posIdsRef.current !== ids) {
      const was = new Map(posIdsRef.current.map((id, i) => [id, i]));
      posRef.current = ids.flatMap((id) => {
        const i = was.get(id);
        return i === undefined ? [NaN, NaN] : [P[i * 2] ?? NaN, P[i * 2 + 1] ?? NaN];
      });
    }
    posIdsRef.current = ids;
    if (drawnRef.current.length !== n * 2) drawnRef.current = new Float64Array(n * 2);
    if (unitRef.current.length !== n) unitRef.current = new Float64Array(n).fill(NaN);
  }, [ids, n, posRef, posIdsRef, drawnRef, unitRef]);

  // After every render: find the marks React drew and paint them where they are now. The dots
  // and lines only change with the data; a reading re-renders the names and its few copies.
  useLayoutEffect(() => {
    const fresh = paintedGraphRef.current !== graph || marksRef.current.nodes.size !== batches.nodes.length;
    marksRef.current = {
      nodes: fresh ? marksById<SVGPathElement>(nodeLayerRef.current) : marksRef.current.nodes,
      links: fresh ? marksById<SVGPathElement>(linkLayerRef.current) : marksRef.current.links,
      names: marksById<SVGTextElement>(nameLayerRef.current),
      litNodes: marksById<SVGCircleElement>(litNodeLayerRef.current),
      litLinks: marksById<SVGLineElement>(litLinkLayerRef.current),
    };
    paintedGraphRef.current = graph;
    if (fresh) lastKRef.current = NaN;
    paintRef.current(fresh ? "all" : "names");
  });

  return { anchorOf: (i: number) => anchorOf(R, graph, i) };
}

"use client";

import { useEffect, type Dispatch, type SetStateAction } from "react";
import { animate } from "motion/react";
import { duration } from "../../motion/tokens";
import { changeCurve } from "../flow-utils";
import { BUDGET } from "./layout";
import type { Graph } from "./model";
import type { GraphRefs } from "./refs";
import { createForceSimulation, type ForceSimulationOptions } from "./simulation";

/** What the layout needs: the refs, the graph, the box's shape and the simulation options as a key. */
export type SimulationInput = {
  R: GraphRefs;
  graph: Graph;
  n: number;
  /** The box's width / height in coarse steps (0 before it is measured). */
  aspect: number;
  /** `JSON.stringify(forces ?? {})`: the options compared by value, so an inline object does not re-run the layout. */
  forcesKey: string;
  /** Bump the "settled" counter once motion stops. */
  settle: () => void;
  setLayoutVersion: Dispatch<SetStateAction<number>>;
};

/**
 * The force layout: computed in small chunks between frames (never a long task), then shown. Known nodes keep
 * their place and glide to where the new layout settles; new ones appear in place. Returns `startLive`, which runs
 * the simulation frame by frame while a node is dragged.
 */
export function useSimulationLayout({ R, graph, n, aspect, forcesKey, settle, setLayoutVersion }: SimulationInput) {
  const { simRef, posRef, finalRef, centreRef, glideRef, liveRafRef, reducedRef, paintRef } = R;

  function stopLive() {
    cancelAnimationFrame(liveRafRef.current);
    liveRafRef.current = 0;
  }

  useEffect(() => {
    if (aspect === 0) return;
    if (n === 0) {
      simRef.current = null;
      posRef.current = null;
      finalRef.current = null;
      return;
    }
    // Known nodes start where they are; new ones next to a known neighbour.
    const prev = posRef.current;
    const at = (i: number) => {
      const x = prev?.[i * 2];
      const y = prev?.[i * 2 + 1];
      return x !== undefined && y !== undefined && Number.isFinite(x) && Number.isFinite(y) ? { x, y } : null;
    };
    const had = !!prev && graph.nodes.some((_, i) => at(i) !== null);
    const init = had
      ? graph.nodes.map(
          (g, i) => at(i) ?? g.neighbours.map(at).find(Boolean) ?? { x: Math.cos(i) * 20, y: Math.sin(i) * 20 },
        )
      : null;
    const sim = createForceSimulation(
      graph.nodes.map((g) => g.r),
      graph.links.map((l) => ({ source: l.s, target: l.t })),
      init,
      { aspect, ...(JSON.parse(forcesKey) as ForceSimulationOptions | undefined) },
    );
    if (had) sim.alpha = 0.6;
    simRef.current = sim;
    stopLive();
    let raf = 0;
    const step = () => {
      const t0 = performance.now();
      while (sim.alpha > sim.alphaMin && performance.now() - t0 < BUDGET) sim.tick();
      if (sim.alpha > sim.alphaMin) {
        raf = requestAnimationFrame(step);
        return;
      }
      const next = sim.positions();
      finalRef.current = next;
      let sx = 0;
      let sy = 0;
      for (let i = 0; i < n; i++) {
        sx += next[i * 2] ?? 0;
        sy += next[i * 2 + 1] ?? 0;
      }
      centreRef.current = { x: sx / n, y: sy / n };
      glideRef.current?.stop();
      if (had && !reducedRef.current) {
        // Glide from where each node was to where it settled (new nodes appear in place).
        const from = graph.nodes.flatMap((_, i) => {
          const p = at(i) ?? { x: next[i * 2] ?? 0, y: next[i * 2 + 1] ?? 0 };
          return [p.x, p.y];
        });
        const controls = animate(0, 1, {
          duration: duration.slower,
          ease: "linear",
          onUpdate: (k) => {
            const e = changeCurve(k);
            posRef.current = from.map((v, j) => v + ((next[j] ?? v) - v) * e);
            paintRef.current("all");
          },
          onComplete: settle,
        });
        glideRef.current = controls;
      } else {
        posRef.current = next;
        paintRef.current("all");
      }
      setLayoutVersion((v) => v + 1);
    };
    raf = requestAnimationFrame(step);
    return () => {
      cancelAnimationFrame(raf);
      glideRef.current?.stop();
    };
    // `settle` and `stopLive` are fresh closures every render over the same refs; only the data, options and box shape re-run the layout.
    // eslint-disable-next-line react-hooks/exhaustive-deps -- the layout re-runs for new data, new options or a new box shape, not for a new render's closures
  }, [
    graph,
    forcesKey,
    aspect,
    n,
    simRef,
    posRef,
    finalRef,
    centreRef,
    glideRef,
    reducedRef,
    paintRef,
    setLayoutVersion,
  ]);

  function startLive() {
    if (liveRafRef.current || reducedRef.current) return;
    const loop = () => {
      const sim = simRef.current;
      if (!sim) {
        liveRafRef.current = 0;
        return;
      }
      sim.tick();
      const next = sim.positions();
      finalRef.current = next;
      posRef.current = next;
      paintRef.current("all");
      if (sim.alpha > sim.alphaMin || sim.alphaTarget > 0) liveRafRef.current = requestAnimationFrame(loop);
      else {
        liveRafRef.current = 0;
        settle();
      }
    };
    liveRafRef.current = requestAnimationFrame(loop);
  }
  useEffect(() => () => cancelAnimationFrame(liveRafRef.current), [liveRafRef]);

  return { startLive };
}

"use client";

import { useEffect, useEffectEvent } from "react";
import { animate } from "motion/react";
import { duration } from "../../motion/tokens";
import { clamp } from "../chart-utils";
import { enterCurve } from "../flow-utils";
import { K_MAX, K_MIN, type View } from "./layout";
import type { Graph } from "./model";
import type { GraphRefs } from "./refs";

/** What the view needs: the refs, the graph, the box and the layout's version (a new layout re-fits the view). */
export type ViewInput = {
  R: GraphRefs;
  graph: Graph;
  n: number;
  width: number;
  height: number;
  layoutVersion: number;
  /** The active node and how it was chosen: a keyboard move keeps its node in view. */
  act: number | null;
  source: "keyboard" | "pointer";
  settle: () => void;
};

/**
 * The view (zoom and pan): one transform on the graph's layer. Fits the graph when a layout lands or the box
 * resizes (unless the reader has zoomed or panned), tweens zooms and keeps the keyboard's node in view. Returns the
 * view setters and the screen / simulation coordinate helpers.
 */
export function useGraphView({ R, graph, n, width, height, layoutVersion, act, source, settle }: ViewInput) {
  const { viewRef, viewTweenRef, reducedRef, paintRef, finalRef, userMovedRef, fittedForRef, drawnRef } = R;

  const setView = (v: View) => {
    viewRef.current = v;
    paintRef.current("view");
  };
  const animateView = (to: View, instant = reducedRef.current) => {
    viewTweenRef.current?.stop();
    if (instant) {
      setView(to);
      settle();
      return;
    }
    const from = viewRef.current;
    viewTweenRef.current = animate(0, 1, {
      duration: duration.slow,
      ease: "linear",
      onUpdate: (t) => {
        const e = enterCurve(t);
        setView({
          k: from.k + (to.k - from.k) * e,
          tx: from.tx + (to.tx - from.tx) * e,
          ty: from.ty + (to.ty - from.ty) * e,
        });
      },
      onComplete: settle,
    });
  };

  const fitView = (P: number[] | null): View => {
    if (!P || n === 0 || width === 0) return { k: 1, tx: width / 2, ty: height / 2 };
    let x0 = Infinity;
    let y0 = Infinity;
    let x1 = -Infinity;
    let y1 = -Infinity;
    graph.nodes.forEach((g, i) => {
      const x = P[i * 2] ?? 0;
      const y = P[i * 2 + 1] ?? 0;
      x0 = Math.min(x0, x - g.r);
      x1 = Math.max(x1, x + g.r);
      y0 = Math.min(y0, y - g.r);
      y1 = Math.max(y1, y + g.r);
    });
    // Room for names on the right and the zoom buttons at the top.
    const padX = 28;
    const padY = 26;
    const k = clamp(
      Math.min((width - padX * 2 - 40) / Math.max(1, x1 - x0), (height - padY * 2) / Math.max(1, y1 - y0)),
      K_MIN,
      2,
    );
    return { k, tx: width / 2 - ((x0 + x1) / 2) * k - 20, ty: height / 2 - ((y0 + y1) / 2) * k };
  };

  // Fit when a layout lands or the box resizes (unless the reader has zoomed or panned).
  const fitTo = useEffectEvent((P: number[], instant: boolean) => animateView(fitView(P), instant));
  useEffect(() => {
    const final = finalRef.current;
    if (!final || width === 0) return;
    const key = `${layoutVersion}|${width}|${height}`;
    const prevKey = fittedForRef.current;
    if (prevKey === key) return;
    fittedForRef.current = key;
    if (userMovedRef.current) return;
    // The first fit and resizes are instant; a new layout glides there.
    fitTo(final, prevKey === "" || prevKey.startsWith(`${layoutVersion}|`) || reducedRef.current);
  }, [layoutVersion, width, height, finalRef, fittedForRef, userMovedRef, reducedRef]);

  /** Zoom by `factor` around a point (default: the centre of the box). */
  function zoomBy(factor: number, at?: { x: number; y: number }, instant = false) {
    const v = viewRef.current;
    const k = clamp(v.k * factor, K_MIN, K_MAX);
    const ax = at?.x ?? width / 2;
    const ay = at?.y ?? height / 2;
    const cx = (ax - v.tx) / v.k;
    const cy = (ay - v.ty) / v.k;
    userMovedRef.current = true;
    animateView({ k, tx: ax - cx * k, ty: ay - cy * k }, instant || reducedRef.current);
  }
  function fit() {
    userMovedRef.current = false;
    animateView(fitView(finalRef.current));
  }

  /* ---------- Screen px and simulation units ---------- */

  const screenOf = (i: number) => {
    const v = viewRef.current;
    return { x: (drawnRef.current[i * 2] ?? NaN) * v.k + v.tx, y: (drawnRef.current[i * 2 + 1] ?? NaN) * v.k + v.ty };
  };
  const toSim = (sx: number, sy: number) => ({
    x: (sx - viewRef.current.tx) / viewRef.current.k,
    y: (sy - viewRef.current.ty) / viewRef.current.k,
  });

  // Keep the keyboard's node in view (the view and size are read when the node changes, not watched).
  const keepInView = useEffectEvent((node: number) => {
    const v = viewRef.current;
    const { x: sx, y: sy } = screenOf(node);
    if (!Number.isFinite(sx) || !Number.isFinite(sy)) return;
    const m = 40;
    let dx = 0;
    let dy = 0;
    if (sx < m) dx = m - sx;
    else if (sx > width - m - 60) dx = width - m - 60 - sx;
    if (sy < m) dy = m - sy;
    else if (sy > height - m) dy = height - m - sy;
    if (dx || dy) animateView({ k: v.k, tx: v.tx + dx, ty: v.ty + dy });
  });
  useEffect(() => {
    if (act !== null && source === "keyboard") keepInView(act);
  }, [act, source]);

  return { setView, animateView, fitView, zoomBy, fit, screenOf, toSim };
}

